function sourceNoteFor(i,y){
 if(i===0&&y<-700)return 'Mốc '+Math.abs(y)+' TCN thuộc niên đại truyền thống Hồng Bàng. Đường chấm là vùng 15 bộ của Văn Lang theo sử cũ, đặt vào địa danh ngày nay theo Trần Trọng Kim và Đào Duy Anh: Bắc Bộ và Bắc Trung Bộ, từ Cao Bằng, Lạng Sơn tới Quảng Bình, Quảng Trị. Đại Việt sử ký toàn thư còn chép một phạm vi rộng tới hồ Động Đình và Ba Thục (nay thuộc Trung Quốc); lời chép ấy được ghi muộn (thế kỷ XV) và được xem là truyền thuyết, nên bản đồ không vẽ.'+(y<-2000?' Trước khoảng 2000 TCN chưa có văn hóa khảo cổ nào nối thẳng với Văn Lang để vẽ.':' Vùng tô là phạm vi có di chỉ của giai đoạn này theo khảo cổ học: ở sông Hồng (Phú Thọ, Vĩnh Phúc, Hà Nội, Bắc Ninh, Bắc Giang, Hải Phòng) và sông Mã (Thanh Hóa)'+(y>=-1000?', muộn hơn có cả sông Lam (Nghệ An)':'')+'. Đó là nơi cư dân sống, không phải đường biên của một nhà nước.');
 if(i===0)return 'Từ khoảng thế kỷ VII TCN, bằng chứng Đông Sơn tập trung mạnh ở ba lưu vực sông Hồng, sông Mã và sông Cả. Vùng tô là một bao địa lý xấp xỉ cho địa bàn chủ yếu ở Bắc Bộ–Bắc Trung Bộ, dùng để định hướng không gian Văn Lang, không phải đường biên quốc gia.';
 return PERIOD_SOURCES[i].note;
}

function clipLat(poly,minLat,maxLat){
 let out=poly.slice();
 const clip=(arr,bound,keepAbove)=>{const r=[];for(let i=0;i<arr.length;i++){const a=arr[i],b=arr[(i+1)%arr.length],ain=keepAbove?a[0]>=bound:a[0]<=bound,bin=keepAbove?b[0]>=bound:b[0]<=bound;if(ain)r.push(a);if(ain!==bin){const t=(bound-a[0])/(b[0]-a[0]);r.push([bound,a[1]+(b[1]-a[1])*t])}}return r};
 out=clip(out,minLat,true);out=clip(out,maxLat,false);return out;
}
