function overlayFor(i,y){
 if(i===0){
  if(y>=-700)return [L('archaeology','vanLangEvidenceZone','Địa bàn chủ yếu Văn Lang — Bắc Bộ · Bắc Trung Bộ (xấp xỉ)')];
  const told=L('tradition','vanLang15Bo','15 bộ Văn Lang (theo truyền thống)');
  if(y<-2000)return [told];
  const sites=y<-1500?L('archaeology','phungNguyenZone','Vùng có di chỉ, ~2000–1500 TCN'):y<-1000?L('archaeology','dongDauZone','Vùng có di chỉ, ~1500–1000 TCN'):L('archaeology','goMunZone','Vùng có di chỉ, ~1000–700 TCN');
  return [sites,told];
 }
 if(i===12)return [L('reconstruction',y>=1069?'realm1069':'realmPre1069',y>=1069?'Đại Việt sau mốc 1069':'Đại Việt trước mốc 1069')];
 if(i===13)return [L('reconstruction',y>=1306?'realm1306':'realm1069',y>=1306?'Đại Việt sau Châu Ô–Châu Lý (1306)':'Đại Việt trước 1306')];
 if(i===15){const a=[L('administration','realm1306','Giao Chỉ thuộc Minh')];if(y>=1425)a.push(L('control-b','lamSonWide','Vùng giải phóng Lam Sơn — khái quát'));else if(y>=1418)a.push(L('control-b','lamSonSmall','Căn cứ Lam Sơn'));return a}
 if(i===16)return [L('reconstruction',y>=1471?'realm1471':'realm1306',y>=1471?'Đại Việt sau Quảng Nam thừa tuyên (1471)':'Đại Việt trước 1471')];
 if(i===17&&y>=1592)return [L('control-a','macNorth','Mạc rút lên Cao Bằng — khái quát'),L('control-b','realm1306','Lê–Trịnh kiểm soát phần lớn Đại Việt')];
 if(i===18){const k=y>=1757?'nguyen1757':y>=1698?'nguyen1698':y>=1653?'nguyen1653':y>=1611?'nguyen1611':'nguyen1600';return [L('control-a','trinhNorth','Đàng Ngoài'),L('control-b',k,'Đàng Trong — phạm vi theo mốc mở cõi')];}
 if(i===19){if(y>=1795)return [L('control-a','realm1306','Tây Sơn thu hẹp ở Bắc–Trung'),L('control-b','nguyenRecovery','Nguyễn Ánh phục hồi từ phía Nam')];if(y>=1786)return [L('control-a','taySonWide','Tây Sơn kiểm soát phần lớn Bắc–Trung'),L('control-b','nguyenGiaDinh','Nguyễn Ánh / Gia Định')];return overlayPlan[i]}
 if(i===23&&y>=1950)return [L('control-a','vietMinhBase','Việt Minh / VNDCCH — căn cứ mở rộng'),L('control-b','frenchLowlands','Pháp / QGVN — đô thị và đồng bằng khái quát')];
 return overlayPlan[i]
}
function periodView(i,y){
 if(i===0)return y>=-700?{lat:20.15,lon:105.45,zoom:6}:{lat:20.00,lon:105.70,zoom:6};
 if(i===1)return{lat:21.08,lon:105.82,zoom:7};
 if(i===2)return{lat:22.6,lon:109.5,zoom:5};
 if(i===3)return{lat:18.8,lon:106.2,zoom:5};
 if(i===4)return{lat:21.1,lon:105.6,zoom:6};
 if(i===5||i===7)return{lat:19.5,lon:105.8,zoom:5};
 if(i===6||i===8||i===9||i===10||i===11)return{lat:20.4,lon:105.5,zoom:5};
 if(i>=12&&i<=17)return{lat:19.0,lon:106.0,zoom:5};
 if(i===18)return y>=1698?{lat:13.4,lon:106.3,zoom:5}:{lat:15.7,lon:106.8,zoom:5};
 if(i===19)return{lat:14.3,lon:106.6,zoom:5};
 if(i===23)return{lat:20.0,lon:105.5,zoom:5};
 if(i===24||i===25)return{lat:16.95,lon:106.65,zoom:7};
 return{lat:16.2,lon:106.4,zoom:5}
}
const MARITIME_GROUPS=[
 {name:'Hoàng Sa / Paracel Islands',label:[16.66,112.03],points:[[16.5342,111.6072],[16.8344,112.3397],[16.9636,112.3103],[16.4497,111.7075]],modern:'Việt Nam tuyên bố chủ quyền · hiện do Trung Quốc kiểm soát'},
 {name:'Trường Sa / Spratly Islands',label:[10.10,113.38],points:[[8.6453,111.9200],[8.9308,112.3531],[9.8853,114.3297],[11.3875,114.2983],[11.0533,114.2847],[7.8917,112.9211]],modern:'Việt Nam tuyên bố chủ quyền · nhiều bên kiểm soát các thực thể'}
];
function drawMaritimeLayer(svg,w,h){
 if(selected<20)return;
 for(const g of MARITIME_GROUPS){
  for(const [lat,lon] of g.points){const q=project(lat,lon,w,h),r=3.5;svg.insertAdjacentHTML('beforeend',`<path class="maritime-feature" d="M ${q.x} ${q.y-r} L ${q.x+r} ${q.y} L ${q.x} ${q.y+r} L ${q.x-r} ${q.y} Z"/>`)}
  const q=project(g.label[0],g.label[1],w,h),sub=selected>=27?g.modern:'Quần đảo — tham chiếu địa lý';
  const lines=w<480?[g.name.split(' / ')[0]]:[g.name,...sub.split(' · ')];svg.insertAdjacentHTML('beforeend',`<g>${lines.map((t,i)=>`<text class="${i?'maritime-sub':'maritime-label'}" x="${q.x+8}" y="${q.y+(i?2+11*i:0)}">${t}</text>`).join('')}</g>`);const texts=[...svg.lastElementChild.querySelectorAll('text')],x=Math.min(q.x+8,w-6-Math.max(...texts.map(t=>t.getComputedTextLength())));if(x<q.x+8)texts.forEach(t=>t.setAttribute('x',x))
 }
}

function smoothClosedPath(shape,w,h){
 const pts=shape.map(([a,o])=>project(a,o,w,h));if(pts.length<3)return'';
 const mid=(a,b)=>({x:(a.x+b.x)/2,y:(a.y+b.y)/2});const first=mid(pts[pts.length-1],pts[0]);let d=`M ${first.x.toFixed(1)} ${first.y.toFixed(1)}`;
 for(let i=0;i<pts.length;i++){const n=pts[(i+1)%pts.length],m=mid(pts[i],n);d+=` Q ${pts[i].x.toFixed(1)} ${pts[i].y.toFixed(1)} ${m.x.toFixed(1)} ${m.y.toFixed(1)}`}
 return d+' Z'
}
function renderMapSources(){const group=PERIOD_SOURCES[selected],body=$('mapSourceBody');body.innerHTML=group.ids.map(id=>{const x=MAP_SOURCE_CATALOG[id];return `<a href="${x.url}" target="_blank" rel="noopener">↗ ${x.title}</a>`}).join('')+'<a href="https://www.naturalearthdata.com/" target="_blank" rel="noopener">↗ Natural Earth — nền địa lý: bờ biển, sông, hồ, biên giới hiện đại</a>'+`<div class="source-note">${sourceNoteFor(selected,year)}</div>`}
const detailTitles=['Nhà nước & chính trị','Lãnh thổ & địa lý','Xã hội & kinh tế','Văn hóa & tư tưởng','Đối ngoại & chiến tranh','Di sản & chuyển tiếp'];
let peopleVisibleLimit=36,selectedPersonId=null;
function personAliveInYear(p,y){return p.birth!=null&&p.birth<=y&&(p.death==null||p.death>=y)}
function filteredPeople(){const q=normText($('peopleSearch')?.value||''),era=$('peopleEra')?.value??'',rel=$('peopleRelevance')?.value||'',region=$('peopleRegion')?.value||'',role=$('peopleRole')?.value||'',timeMode=$('peopleTime')?.value||'all';return PEOPLE.filter(p=>{if(q&&!normText([p.name,...(p.alt||[]),p.polity,p.region,...p.roles,p.summary].join(' ')).includes(q))return false;if(era!==''&&!personOverlapsEra(p,+era))return false;if(rel&&p.relevance!==rel)return false;if(region&&p.region!==region)return false;if(role&&!p.roles.includes(role))return false;if(timeMode==='alive'&&!personAliveInYear(p,year))return false;if(timeMode==='period'&&!personOverlapsEra(p,selected))return false;return true}).sort((a,b)=>{const rank={direct:0,regional:1,world:2};return (rank[a.relevance]-rank[b.relevance])||((a.birth??9999)-(b.birth??9999))||a.name.localeCompare(b.name,'vi')})}
function personLifeLabel(p){return `${p.birthLabel||'Không rõ'} – ${p.deathLabel||'Không rõ'}`}
function relevanceLabel(v){return v==='direct'?'Trực tiếp':v==='regional'?'Khu vực':'Thế giới cùng thời'}
function renderPeopleHub(){if(!$('peopleGrid'))return;const all=filteredPeople(),shown=all.slice(0,peopleVisibleLimit),aliveCount=PEOPLE.filter(p=>personAliveInYear(p,year)).length,timeMode=$('peopleTime')?.value||'all';$('peopleCount').textContent=`${all.length} nhân vật phù hợp`;$('peopleYearContext').innerHTML=`<strong>${fmt(year)}</strong> · ${aliveCount} nhân vật trong kho có niên đại xác định bao phủ năm này.`;$('peopleUseYear').textContent=timeMode==='alive'?'Bỏ lọc theo năm':'Chỉ xem người sống trong năm này';$('peopleGrid').innerHTML=shown.length?shown.map(p=>`<button class="person-card" type="button" data-person="${p.id}"><span class="person-kicker"><span class="relevance-${p.relevance}">${relevanceLabel(p.relevance)}</span><span>${p.region}</span></span><strong>${p.name}</strong><span class="person-life">${personLifeLabel(p)} · ${p.polity}</span><p>${p.summary}</p><span class="person-tags">${p.roles.slice(0,3).map(r=>`<span>${r}</span>`).join('')}</span></button>`).join(''):`<div class="people-empty">Không tìm thấy nhân vật phù hợp. Hãy thử bỏ bớt bộ lọc hoặc tìm bằng tên khác.</div>`;$('peopleGrid').querySelectorAll('.person-card').forEach(b=>b.onclick=()=>openPerson(b.dataset.person));$('peopleMore').hidden=shown.length>=all.length}
function populatePeopleFilters(){if(!$('peopleEra'))return;$('peopleEra').insertAdjacentHTML('beforeend',P.map((p,i)=>`<option value="${i}">${String(i+1).padStart(2,'0')} · ${p[2]}</option>`).join(''));for(const [id,key] of [['peopleRegion','region'],['peopleRole','roles']]){const values=[...new Set(PEOPLE.flatMap(p=>key==='roles'?p.roles:[p[key]]))].filter(Boolean).sort((a,b)=>a.localeCompare(b,'vi'));$(id).insertAdjacentHTML('beforeend',values.map(v=>`<option value="${v}">${v}</option>`).join(''))}}
const PERSON_TABS=[['story','Câu chuyện'],['life','Dòng đời'],['relations','Quan hệ'],['vietnam','Việt Nam'],['places','Địa điểm'],['contemporary','Cùng thời'],['sources','Nguồn']];
let personTab='story';
function personEraIndexes(person){const set=new Set(person.eraHints||[]);P.forEach((_,i)=>{if(personOverlapsEra(person,i))set.add(i)});return [...set].sort((a,b)=>a-b)}
function personContemporaries(person){let candidates=PEOPLE.filter(x=>x.id!==person.id);if(person.birth!=null){const end=person.death??2026;candidates=candidates.filter(x=>x.birth!=null&&(x.death??2026)>=person.birth&&x.birth<=end)}else if(person.eraHints?.length){candidates=candidates.filter(x=>x.eraHints?.some(i=>person.eraHints.includes(i)))}else candidates=[];const relevanceRank={direct:0,regional:1,world:2};return candidates.sort((a,b)=>{const ad=a.region===person.region?1:0,bd=b.region===person.region?1:0;return ad-bd||(relevanceRank[a.relevance]-relevanceRank[b.relevance])||a.name.localeCompare(b.name,'vi')}).slice(0,12)}
function personInitials(name){return name.replace(/\([^)]*\)/g,'').trim().split(/\s+/).slice(-2).map(x=>x[0]||'').join('').toUpperCase()||'人'}
function personStory(person){const events=person.events||[],relations=person.relations||[];return `<div class="person-profile-grid"><div><p class="person-lead">${person.summary}</p><div class="person-story-beat"><small>Bối cảnh</small><h5>${person.name} nằm ở đâu trong lịch sử?</h5><p>${person.story||person.summary} ${person.polity?`Hồ sơ đặt nhân vật trong không gian <strong>${person.polity}</strong>, thay vì tách họ khỏi chính thể và thời đại.`:''}</p></div><div class="person-story-beat"><small>Bước ngoặt</small><h5>${events.length?'Những mốc làm thay đổi câu chuyện':'Đọc người này qua bối cảnh và quan hệ'}</h5><p>${events.length?events.map(x=>`<strong>${x}</strong>`).join(' · '):relations.length?`Các quan hệ được ghi nhận trong hồ sơ giúp đi tiếp sang ${relations.slice(0,3).map(r=>personById(r.id)?.name).filter(Boolean).join(', ')}.`:'Hồ sơ hiện chưa gắn một danh sách sự kiện riêng; hãy dùng các thời kỳ và nguồn ở những tab bên cạnh để tiếp tục tra cứu.'}</p></div><div class="person-story-beat"><small>Vì sao quan trọng với Sử Việt</small><h5>${relevanceLabel(person.relevance)}</h5><p>${person.vietnamLink}</p></div></div><div class="person-factbox"><div><small>Niên đại</small><strong>${personLifeLabel(person)}</strong></div><div><small>Chính thể / quốc gia</small><strong>${person.polity}</strong></div><div><small>Khu vực</small><strong>${person.region}</strong></div><div><small>Vai trò</small><strong>${person.roles.join(' · ')}</strong></div><div><small>Độ chắc chắn</small><strong>${person.confidence||'Khá chắc'}</strong></div></div></div>`}
function personLifeMarkup(person){const rows=[];if(person.birth!=null||person.birthLabel!=='Không rõ')rows.push({t:person.birthLabel,title:'Sinh / xuất hiện trong sử liệu',text:`Mốc sinh hoặc niên đại sớm nhất được dùng trong hồ sơ của ${person.name}.`});(person.events||[]).forEach(e=>rows.push({t:'',title:e,text:'Sự kiện nổi bật gắn với nhân vật trong dòng thời gian Sử Việt.'}));if(person.death!=null)rows.push({t:person.deathLabel,title:'Qua đời',text:`Kết thúc đời sống của ${person.name}; ảnh hưởng lịch sử có thể tiếp tục rất lâu sau đó.`});const eras=personEraIndexes(person);return `<h4>Dòng đời · ${person.name}</h4><p>Đây là trục đọc nhanh; với nhân vật huyền sử hoặc niên đại bất định, atlas không tự bịa ngày tháng để lấp khoảng trống.</p><div class="person-lifeline">${rows.length?rows.map(r=>`<div><strong>${r.t?`${r.t} · `:''}${r.title}</strong><span>${r.text}</span></div>`).join(''):'<div><strong>Niên đại chưa đủ chắc</strong><span>Dùng thời kỳ liên quan và nguồn để đọc thay vì áp một niên biểu giả chính xác.</span></div>'}</div><div class="person-era-actions">${eras.map(i=>`<button class="person-era-button" type="button" data-era="${i}">${P[i][2]}</button>`).join('')}</div>`}
function relationsMarkup(person){const rels=(person.relations||[]).map(r=>({r,p:personById(r.id)})).filter(x=>x.p);return `<h4>Quan hệ · ${person.name}</h4><p>Quan hệ ở đây chỉ hiển thị khi hồ sơ có một liên kết lịch sử cụ thể; chúng không được suy đoán từ việc hai người sống cùng thời.</p><div class="person-link-grid">${rels.length?rels.map(({r,p})=>`<button class="relation-person" type="button" data-person-link="${p.id}"><strong>${p.name}</strong><small>${r.type} · ${p.polity}</small></button>`).join(''):'<div class="people-empty">Chưa có quan hệ đã được mã hóa cho hồ sơ này. Dùng tab “Cùng thời” để mở rộng theo thời gian thay vì giả lập quan hệ.</div>'}</div>`}
function vietnamMarkup(person){const eras=personEraIndexes(person);const cls=person.relevance==='world'?'person-world-note':'reader-source-note';return `<h4>Liên hệ với Việt Nam</h4><div class="${cls}">${person.vietnamLink}</div><div class="person-role-chips"><span>${relevanceLabel(person.relevance)}</span><span>${person.region}</span>${person.roles.map(r=>`<span>${r}</span>`).join('')}</div><h5>Thời kỳ Sử Việt giao nhau</h5><div class="person-era-actions">${eras.length?eras.map(i=>`<button class="person-era-button" type="button" data-era="${i}">${fmt(P[i][0])}–${fmt(P[i][1])} · ${P[i][2]}</button>`).join(''):'<span class="person-empty">Không gán niên đại chính xác vì dữ liệu không đủ chắc.</span>'}</div>`}
function focusPersonPlace(place){if(!place||!Number.isFinite(+place.lat)||!Number.isFinite(+place.lon))return;center={lat:+place.lat,lon:+place.lon};zoom=Math.abs(place.lon)>125||Math.abs(place.lat)>30?5:6;drawMap();const n=$('personMapNotice');if(n)n.textContent=`Bản đồ chính đã chuyển tới ${place.name}. Đóng hồ sơ để xem vị trí trên bản đồ lịch sử.`}
function placesMarkup(person){const ps=person.places||[];return `<h4>Địa điểm trong cuộc đời</h4><p>Các điểm này là địa danh tham chiếu, không phải đường đi chính xác của nhân vật.</p><div class="person-place-list">${ps.length?ps.map((x,i)=>`<button class="person-place" type="button" data-place="${i}"><strong>${x.name}</strong><span>${x.note||''} · ${(+x.lat).toFixed(2)}°, ${(+x.lon).toFixed(2)}°</span></button>`).join(''):'<span class="person-empty">Chưa có địa điểm đã được kiểm tra và gắn vào hồ sơ này.</span>'}</div><div class="person-map-notice" id="personMapNotice">Chọn một địa điểm để đưa bản đồ chính tới vị trí đó.</div>`}
function contemporaryMarkup(person){const xs=personContemporaries(person);return `<h4>Ai đang sống cùng thời?</h4><p>Danh sách ưu tiên người từ khu vực khác để bạn có thể đi từ lịch sử Việt Nam ra thế giới. “Cùng thời” không có nghĩa họ từng gặp nhau hay có quan hệ trực tiếp.</p><div class="person-link-grid">${xs.length?xs.map(p=>`<button class="contemporary-person" type="button" data-person-link="${p.id}"><strong>${p.name}</strong><small>${personLifeLabel(p)} · ${p.region} · ${relevanceLabel(p.relevance)}</small></button>`).join(''):'<div class="people-empty">Không đủ niên đại chắc để tự động tìm người cùng thời.</div>'}</div>`}
function sourcesMarkup(person){const eras=personEraIndexes(person),sourceIds=[...new Set(eras.flatMap(i=>PERIOD_SOURCES[i]?.ids||[]))].slice(0,8);const q=encodeURIComponent(person.sourceQuery||person.name);return `<h4>Nguồn & hướng tra cứu</h4><p>Hai liên kết đầu là điểm bắt đầu tra cứu tiểu sử. Nguồn thời kỳ bên dưới dùng để đặt nhân vật vào bối cảnh lịch sử của Sử Việt; không có nghĩa mỗi nguồn đều là chuyên khảo riêng về người này.</p><a class="person-source-link" target="_blank" rel="noopener" href="https://vi.wikipedia.org/w/index.php?search=${q}">↗ Wikipedia tiếng Việt — tra cứu ${person.name}</a><a class="person-source-link" target="_blank" rel="noopener" href="https://www.britannica.com/search?query=${q}">↗ Encyclopaedia Britannica — tra cứu ${person.name}</a>${sourceIds.map(id=>{const x=MAP_SOURCE_CATALOG[id];return x?`<a class="person-source-link" target="_blank" rel="noopener" href="${x.url}">↗ ${x.title}</a>`:''}).join('')}<div class="reader-source-note">Độ chắc chắn hồ sơ: ${person.confidence||'Khá chắc'}. Với huyền sử, atlas giữ nhãn bất định thay vì biến truyền thuyết thành dữ kiện tiểu sử.</div>`}
function personContent(person,tab){if(tab==='story')return personStory(person);if(tab==='life')return personLifeMarkup(person);if(tab==='relations')return relationsMarkup(person);if(tab==='vietnam')return vietnamMarkup(person);if(tab==='places')return placesMarkup(person);if(tab==='contemporary')return contemporaryMarkup(person);return sourcesMarkup(person)}
function renderPersonProfile(id,tab){const person=personById(id);if(!person)return;selectedPersonId=id;personTab=tab||personTab||'story';$('personAvatar').textContent=personInitials(person.name);$('personEyebrow').textContent=`${relevanceLabel(person.relevance)} · ${person.region}`;$('personTitle').textContent=person.name;$('personMeta').textContent=`${personLifeLabel(person)} · ${person.polity}`;$('personTabs').innerHTML=PERSON_TABS.map(([k,label])=>`<button class="reader-tab" type="button" role="tab" data-person-tab="${k}" aria-selected="${k===personTab}">${label}</button>`).join('');$('personTabs').querySelectorAll('[data-person-tab]').forEach(b=>b.onclick=()=>renderPersonProfile(id,b.dataset.personTab));$('personBody').innerHTML=personContent(person,personTab);$('personBody').querySelectorAll('[data-person-link]').forEach(b=>b.onclick=()=>{personTab='story';renderPersonProfile(b.dataset.personLink,'story');history.replaceState(null,'',`#person=${encodeURIComponent(b.dataset.personLink)}`)});$('personBody').querySelectorAll('[data-era]').forEach(b=>b.onclick=()=>{const i=+b.dataset.era;render(P[i][0]);$('personDialog').close();document.getElementById('explore').scrollIntoView({behavior:'smooth'});history.replaceState(null,'',`#explore`)});$('personBody').querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>focusPersonPlace(person.places[+b.dataset.place]))}
function openPerson(id){const person=personById(id);if(!person)return;selectedPersonId=id;personTab='story';renderPersonProfile(id,'story');const dlg=$('personDialog');if(typeof dlg.showModal==='function'){if(!dlg.open)dlg.showModal()}else dlg.setAttribute('open','');history.replaceState(null,'',`#person=${encodeURIComponent(id)}`)}
function bindPeopleHub(){populatePeopleFilters();['peopleSearch','peopleEra','peopleRelevance','peopleRegion','peopleRole','peopleTime'].forEach(id=>{const el=$(id);if(!el)return;el.addEventListener(id==='peopleSearch'?'input':'change',()=>{peopleVisibleLimit=36;renderPeopleHub()})});$('peopleUseYear').onclick=()=>{const mode=$('peopleTime');mode.value=mode.value==='alive'?'all':'alive';peopleVisibleLimit=36;renderPeopleHub();$('people').scrollIntoView({behavior:'smooth',block:'start'})};$('peopleMore').onclick=()=>{peopleVisibleLimit+=36;renderPeopleHub()};renderPeopleHub()}
