function personById(id){return PEOPLE.find(p=>p.id===id)||null}
function normText(value){return String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase()}
function personOverlapsEra(person,eraIndex){if(person.eraHints?.includes(eraIndex))return true;const e=P[eraIndex];if(!e||person.birth==null)return false;const end=person.death??2026;return person.birth<=e[1]&&end>=e[0]}
