const STORY_DATA=[{"title":"Từ ký ức Hùng Vương đến dấu tích Đông Sơn","lead":"Đây là nơi lịch sử, khảo cổ và truyền thuyết chồng lên nhau. Thay vì kể niên đại truyền thống như một biên niên chính xác, câu chuyện nên cho thấy cách ký ức về các vua Hùng gặp bằng chứng vật chất của cư dân lưu vực sông Hồng, sông Mã và sông Cả.","scenes":[{"kicker":"Bối cảnh","title":"Một quá khứ được nhớ bằng truyền thuyết","text":"Các truyện Lạc Long Quân – Âu Cơ, mười tám đời Hùng Vương và kinh đô Phong Châu thuộc lớp ký ức truyền thống được ghi lại muộn hơn nhiều so với thời đại mà chúng mô tả. Chúng rất quan trọng đối với lịch sử văn hóa Việt Nam, nhưng không thể tự mình chứng minh một biên giới hay một chuỗi vua có niên đại chính xác."},{"kicker":"Bước ngoặt","title":"Đông Sơn làm câu chuyện trở nên hữu hình","text":"Từ thiên niên kỷ I TCN, khảo cổ học cho thấy những cộng đồng nông nghiệp và luyện kim phát triển mạnh ở Bắc Bộ và Bắc Trung Bộ. Trống đồng, mộ táng, vũ khí và mạng lưới cư trú Đông Sơn cho phép ta nói chắc hơn về một không gian văn hóa–xã hội phức tạp, dù việc đồng nhất trực tiếp không gian ấy với “biên giới Văn Lang” vẫn là bước suy luận."},{"kicker":"Hệ quả","title":"Một nhà nước sớm, nhưng không phải bản đồ hiện đại","text":"Văn Lang nên được đọc như một truyền thống về sự hình thành cộng đồng chính trị sớm ở miền Bắc Việt Nam, có liên hệ với tiến trình phân tầng xã hội và tổ chức quyền lực thời Đông Sơn. Càng lùi sâu về mốc 2879 TCN, độ chắc chắn càng thấp; vì thế atlas không vẽ lãnh thổ cho phần niên đại rất sớm."}],"transition":"Câu chuyện tiếp theo là Âu Lạc: một giai đoạn có trung tâm khảo cổ cụ thể hơn ở Cổ Loa, nơi quy mô thành lũy và dấu tích quân sự cho phép chúng ta nói rõ hơn về tổ chức nhà nước.","note":"Huyền sử: các truyện nguồn gốc và niên đại Hùng Vương được trình bày như truyền thống văn hóa, không phải dữ kiện khảo cổ đã được chứng minh."},{"title":"Cổ Loa: khi quyền lực để lại dấu trên mặt đất","lead":"Âu Lạc là bước chuyển quan trọng vì Cổ Loa không chỉ tồn tại trong truyền thuyết: thành lũy, hào nước và hiện vật khảo cổ cho thấy một trung tâm quyền lực quy mô lớn ở châu thổ sông Hồng.","scenes":[{"kicker":"Bối cảnh","title":"Một kinh đô khác hẳn làng xóm thông thường","text":"Việc xây dựng Cổ Loa đòi hỏi huy động lao động, tổ chức vật liệu và kiểm soát một không gian rộng hơn nhiều so với một khu cư trú bình thường. Những vòng thành và hào liên kết với hệ thống sông cho thấy cả nhu cầu phòng thủ lẫn khả năng điều phối của một chính thể đang tập trung quyền lực."},{"kicker":"Bước ngoặt","title":"Nỏ thần và Mỵ Châu–Trọng Thủy","text":"Truyền thuyết kể về nỏ thần, Rùa Vàng và bi kịch Mỵ Châu–Trọng Thủy để giải thích vì sao Âu Lạc thất bại trước Triệu Đà. Câu chuyện phản ánh ký ức về công nghệ quân sự, phòng thủ Cổ Loa và sự đổ vỡ quyền lực, nhưng các chi tiết thần kỳ phải được đọc như huyền thoại chứ không như biên bản chiến tranh."},{"kicker":"Hệ quả","title":"Từ Âu Lạc sang Nam Việt","text":"Cuối cùng vùng Âu Lạc bị đặt dưới quyền Nam Việt của Triệu Đà. Từ đây lịch sử miền Bắc Việt Nam gắn chặt hơn với thế giới chính trị Lĩnh Nam và với các đế chế Trung Hoa, trong khi Cổ Loa tiếp tục sống lâu dài trong ký ức lịch sử Việt Nam."}],"transition":"Sự mất độc lập của Âu Lạc mở ra giai đoạn Nam Việt, một vương quốc có trung tâm ở Phiên Ngung và không thể hiểu bằng cách chỉ nhìn phần đất Việt Nam ngày nay.","note":"Truyền thuyết: nỏ thần và câu chuyện Mỵ Châu–Trọng Thủy được tách khỏi bằng chứng khảo cổ về Cổ Loa."},{"title":"Nam Việt: một vương quốc Lĩnh Nam rộng hơn Việt Nam ngày nay","lead":"Nam Việt của Triệu Đà là một chính thể đa vùng với trung tâm ở Phiên Ngung. Giao Chỉ chỉ là một phần ở phía nam, vì vậy câu chuyện của giai đoạn này phải đặt miền Bắc Việt Nam vào không gian Lĩnh Nam rộng hơn.","scenes":[{"kicker":"Bối cảnh","title":"Sau khi nhà Tần tan rã","text":"Trong thời kỳ hỗn loạn cuối Tần đầu Hán, Triệu Đà xây dựng quyền lực ở vùng Lĩnh Nam và lập nước Nam Việt. Triều đình Phiên Ngung kết hợp nhiều truyền thống địa phương với mô hình chính trị Hoa Hạ, tạo nên một vương quốc biên giới có quan hệ lúc đối đầu, lúc thần phục với nhà Hán."},{"kicker":"Bước ngoặt","title":"Âu Lạc bị sáp nhập","text":"Phần đất của Âu Lạc dần bị đưa vào hệ thống Nam Việt. Điều này không có nghĩa bản sắc và tổ chức địa phương biến mất ngay; thay vào đó, các thủ lĩnh và cộng đồng bản địa tiếp tục tồn tại dưới một tầng quyền lực mới có trung tâm xa về phía bắc."},{"kicker":"Hệ quả","title":"Nhà Hán chinh phục Nam Việt năm 111 TCN","text":"Sau chiến dịch của Hán Vũ Đế, Nam Việt bị sáp nhập vào đế chế Hán. Không gian trước đó thuộc Âu Lạc được tổ chức lại thành các quận như Giao Chỉ, Cửu Chân và Nhật Nam, đưa khu vực bước vào thời kỳ quản trị đế chế trực tiếp hơn."}],"transition":"Từ đây atlas chuyển từ bản đồ một vương quốc Lĩnh Nam sang bản đồ các quận hành chính của nhà Hán — một thay đổi quan trọng trong cách đọc lãnh thổ.","note":""},{"title":"Giao Chỉ dưới nhà Hán: đế chế đi vào làng xã như thế nào?","lead":"Sau năm 111 TCN, miền Bắc và một phần miền Trung Việt Nam được đưa vào mạng lưới hành chính của nhà Hán. Quyền lực đế chế tập trung ở các quận trị và tuyến giao thông, nhưng mức kiểm soát thực tế thay đổi mạnh giữa đồng bằng, ven biển và miền núi.","scenes":[{"kicker":"Bối cảnh","title":"Quan lại, thuế khóa và các hào trưởng địa phương","text":"Nhà Hán cử quan lại và tổ chức quận huyện, trong khi nhiều tầng lớp quyền lực bản địa vẫn giữ vai trò trung gian. Sự tiếp xúc lâu dài làm lan rộng chữ Hán, kỹ thuật, mô hình pháp luật và thương mại, nhưng đồng thời tạo ra xung đột quanh thuế, lao dịch và quyền tự chủ địa phương."},{"kicker":"Bước ngoặt","title":"Luy Lâu trở thành một trung tâm","text":"Luy Lâu ở vùng Bắc Ninh nổi lên như một trung tâm hành chính và giao thương quan trọng. Vị trí trong châu thổ giúp nơi đây kết nối đường sông, đường bộ và mạng lưới biển, góp phần đưa các tôn giáo và văn hóa từ cả Trung Hoa lẫn Nam Á vào khu vực."},{"kicker":"Hệ quả","title":"Căng thẳng tích tụ trước năm 40","text":"Các thay đổi trong quản trị và xung đột giữa quan lại với hào trưởng địa phương tạo môi trường cho cuộc nổi dậy lớn của Hai Bà Trưng. Đó không phải sự kiện tách rời, mà là kết quả của nhiều thập kỷ va chạm giữa chính quyền đế chế và xã hội bản địa."}],"transition":"Năm 40, cuộc khởi nghĩa do Trưng Trắc và Trưng Nhị lãnh đạo làm đứt gãy tạm thời bộ máy Hán ở một vùng rộng, mở ra một trong những câu chuyện nổi tiếng nhất của thời Bắc thuộc.","note":""},{"title":"Hai Bà Trưng: từ Mê Linh đến một cuộc nổi dậy liên vùng","lead":"Cuộc khởi nghĩa năm 40 là một điểm sáng ngắn nhưng có sức sống rất lâu trong ký ức lịch sử. Atlas kể nó như một cuộc nổi dậy chính trị–quân sự có mạng lưới ủng hộ rộng, không biến các con số trong sử cũ thành đường biên chính xác.","scenes":[{"kicker":"Bối cảnh","title":"Mạng lưới hào trưởng và bất mãn địa phương","text":"Trưng Trắc và Trưng Nhị xuất thân từ tầng lớp thủ lĩnh bản địa vùng Mê Linh. Truyền thống sử học gắn khởi nghĩa với cái chết của Thi Sách và sự hà khắc của quan lại Hán; rộng hơn, nó phản ánh khả năng liên kết của nhiều thủ lĩnh địa phương chống lại sự can thiệp ngày càng sâu của bộ máy đô hộ."},{"kicker":"Bước ngoặt","title":"Năm 40: chính quyền Hán bị đánh bật ở nhiều nơi","text":"Khởi nghĩa lan nhanh, nhiều thành và huyện được nói là hưởng ứng. Trưng Trắc được tôn làm vua và đặt trung tâm ở Mê Linh, nhưng thời gian tổ chức chính quyền rất ngắn nên phạm vi kiểm soát thực tế thay đổi nhanh và không thể dựng như một quốc gia có biên giới ổn định."},{"kicker":"Hệ quả","title":"Mã Viện phản công và thất bại năm 43","text":"Nhà Hán điều Mã Viện đem quân trở lại. Sau các trận đánh quyết định, cuộc khởi nghĩa bị dập tắt và quyền kiểm soát đế chế được tái lập. Dù chỉ tồn tại vài năm, Hai Bà Trưng trở thành biểu tượng bền vững về quyền tự chủ và vai trò của phụ nữ trong ký ức lịch sử Việt Nam."}],"transition":"Sau năm 43, chính quyền Hán siết chặt quản trị hơn, nhưng các phong trào chống đối vẫn tiếp diễn trong nhiều thế kỷ, dẫn tới những nhân vật như Bà Triệu và cuối cùng là Lý Bí.","note":""},{"title":"Nhiều thế kỷ trong Giao Châu: không chỉ có “Bắc thuộc”","lead":"Từ thế kỷ I đến đầu thế kỷ VI, khu vực trải qua nhiều triều đại phương Bắc và biến động địa phương. Đây vừa là thời kỳ quản trị đế chế, vừa là thời kỳ giao thương, truyền bá Phật giáo, hình thành các hào tộc và những cuộc nổi dậy.","scenes":[{"kicker":"Bối cảnh","title":"Luy Lâu, Long Biên và mạng lưới giao thương","text":"Các trung tâm ở châu thổ sông Hồng kết nối đường biển với Đông Nam Á và Ấn Độ Dương. Phật giáo sớm phát triển trong môi trường giao lưu đó; đồng thời, chữ viết và mô hình quan liêu từ Trung Hoa ngày càng ăn sâu vào tầng lớp tinh hoa địa phương."},{"kicker":"Bước ngoặt","title":"Bà Triệu và các cuộc nổi dậy","text":"Năm 248, cuộc nổi dậy gắn với Bà Triệu ở Cửu Chân trở thành một biểu tượng lớn khác của truyền thống chống đô hộ. Dù bị đàn áp, những cuộc nổi dậy cho thấy bộ máy đế chế chưa bao giờ kiểm soát đồng đều mọi địa phương và luôn phải dựa vào các cấu trúc quyền lực bản địa."},{"kicker":"Hệ quả","title":"Biên giới phía nam cũng thay đổi","text":"Trong khi Giao Châu hướng về châu thổ sông Hồng, các chính thể ở miền Trung như Lâm Ấp/Champa phát triển mạnh. Vì vậy lịch sử Việt Nam thời kỳ này không chỉ là quan hệ bắc–nam với Trung Hoa mà còn là tương tác liên tục với thế giới Đông Nam Á ven biển."}],"transition":"Đầu thế kỷ VI, sự suy yếu của chính quyền Lương tạo cơ hội để Lý Bí dựng nên Vạn Xuân, lần đầu khôi phục một chính thể độc lập có tên nước riêng sau nhiều thế kỷ.","note":""},{"title":"Vạn Xuân: một lần thử dựng nhà nước độc lập ở thế kỷ VI","lead":"Lý Bí nổi dậy trong bối cảnh chính quyền Lương suy yếu và bất mãn địa phương tăng cao. Việc xưng đế và đặt quốc hiệu Vạn Xuân cho thấy tham vọng xây dựng một trật tự chính trị độc lập chứ không chỉ thay quan cai trị.","scenes":[{"kicker":"Bối cảnh","title":"Lý Bí tập hợp lực lượng và xưng Lý Nam Đế","text":"Sau các thắng lợi ban đầu, Lý Bí lập triều đình, dùng niên hiệu và đặt tên nước Vạn Xuân. Những biểu tượng đó có ý nghĩa lớn: chúng mô phỏng hình thức vương quyền đương thời nhưng khẳng định một trung tâm chính trị riêng ở miền Bắc Việt Nam."},{"kicker":"Bước ngoặt","title":"Kháng chiến chuyển vào đầm lầy Dạ Trạch","text":"Khi quân Lương phản công, lực lượng Vạn Xuân phải rút lui. Triệu Quang Phục dựa vào vùng Dạ Trạch, tận dụng địa hình đầm lầy và lối đánh linh hoạt để tiếp tục kháng chiến, cho thấy chiến tranh không còn là câu chuyện của một kinh đô duy nhất mà là mạng lưới căn cứ và địa hình."},{"kicker":"Hệ quả","title":"Nội bộ chia rẽ rồi nhà Tùy tái chinh phục","text":"Sau khi giành lại được quyền lực, xung đột giữa các nhóm kế tục làm Vạn Xuân suy yếu. Đến đầu thế kỷ VII, nhà Tùy tái lập quyền kiểm soát, mở sang thời kỳ Bắc thuộc lần III dưới Tùy và Đường."}],"transition":"Vạn Xuân để lại tiền lệ quan trọng về việc xưng đế, đặt quốc hiệu và tổ chức kháng chiến dài hạn; những mô thức đó sẽ xuất hiện trở lại trong tiến trình tự chủ về sau.","note":""},{"title":"An Nam đô hộ phủ: đế chế Đường và các cuộc nổi dậy địa phương","lead":"Từ thế kỷ VII đến đầu X, nhà Tùy rồi nhà Đường quản trị khu vực thông qua các đơn vị hành chính mà trung tâm ngày càng gắn với Tống Bình/Đại La. Tuy nhiên, sự kiểm soát luôn bị thử thách bởi nổi dậy, chiến tranh biên giới và khủng hoảng của chính đế chế.","scenes":[{"kicker":"Bối cảnh","title":"Tống Bình–Đại La trở thành trung tâm quyền lực","text":"Vị trí bên sông Hồng khiến Tống Bình và sau đó Đại La trở thành đầu mối hành chính, quân sự và thương mại. Thành lũy được củng cố để bảo vệ bộ máy cai trị trước cả nổi dậy địa phương lẫn các cuộc tấn công từ bên ngoài."},{"kicker":"Bước ngoặt","title":"Mai Thúc Loan, Phùng Hưng và những đợt phản kháng","text":"Các cuộc nổi dậy thế kỷ VIII cho thấy năng lực huy động của các thủ lĩnh địa phương. Dù không tạo ra nhà nước độc lập bền vững, chúng làm rõ rằng quyền lực Đường phải liên tục thương lượng hoặc trấn áp trong một không gian chính trị rất năng động."},{"kicker":"Hệ quả","title":"Khủng hoảng cuối Đường mở cửa cho tự chủ","text":"Thế kỷ IX chứng kiến chiến tranh với Nam Chiếu và sự suy yếu ngày càng rõ của nhà Đường. Khi trung tâm đế chế không còn đủ sức kiểm soát xa, các hào trưởng bản địa như họ Khúc có cơ hội nắm quyền trên thực tế."}],"transition":"Khoảng năm 905, Khúc Thừa Dụ chiếm giữ chức vụ và xây dựng quyền tự chủ tại Tĩnh Hải quân. Đó là cây cầu trực tiếp từ một đơn vị của đế chế sang chính quyền bản địa.","note":""},{"title":"Họ Khúc và Dương Đình Nghệ: độc lập bắt đầu trước khi có một vị vua","lead":"Thời tự chủ đầu thế kỷ X thường ít nổi bật hơn Bạch Đằng 938, nhưng chính giai đoạn này tạo bộ máy và tầng lớp lãnh đạo bản địa đủ mạnh để bước ra khỏi trật tự Đường.","scenes":[{"kicker":"Bối cảnh","title":"Khúc Thừa Dụ nắm Tĩnh Hải quân","text":"Khi nhà Đường suy sụp, Khúc Thừa Dụ nắm quyền tại Đại La. Danh nghĩa chức tước vẫn còn mang dấu vết của hệ thống cũ, nhưng quyền lực thực tế đã chuyển vào tay một dòng họ bản địa — một thay đổi sâu hơn nhiều so với việc đổi tên người đứng đầu."},{"kicker":"Bước ngoặt","title":"Khúc Hạo củng cố quản trị","text":"Truyền thống sử học ghi nhận Khúc Hạo cải tổ đơn vị hành chính và giảm bớt gánh nặng đối với dân. Dù chi tiết cần đọc thận trọng, giai đoạn này cho thấy nỗ lực biến quyền lực quân sự địa phương thành một hệ thống quản trị có khả năng tồn tại lâu dài."},{"kicker":"Hệ quả","title":"Dương Đình Nghệ giành lại Đại La","text":"Nam Hán can thiệp và chiếm Đại La, nhưng Dương Đình Nghệ từ Ái Châu tiến ra đánh bật lực lượng này năm 931. Vụ Kiều Công Tiễn giết Dương Đình Nghệ sau đó lại mở đường cho một cuộc can thiệp mới của Nam Hán — và cho sự xuất hiện của Ngô Quyền."}],"transition":"Cuộc khủng hoảng năm 937–938 đưa lịch sử tới sông Bạch Đằng, nơi Ngô Quyền biến một cuộc tranh chấp kế vị thành bước ngoặt khẳng định nền độc lập lâu dài.","note":""},{"title":"Bạch Đằng 938: một trận đánh thay đổi quỹ đạo lịch sử","lead":"Ngô Quyền không chỉ thắng một trận thủy chiến. Sau nhiều thập kỷ tự chủ mong manh, chiến thắng Bạch Đằng làm thất bại nỗ lực tái can thiệp của Nam Hán và mở ra một trật tự chính trị độc lập bền hơn.","scenes":[{"kicker":"Bối cảnh","title":"Từ vụ Kiều Công Tiễn đến cuộc xâm nhập của Nam Hán","text":"Kiều Công Tiễn giết Dương Đình Nghệ rồi cầu viện Nam Hán. Ngô Quyền kéo quân ra Bắc, xử lý đối thủ trong nước và chuẩn bị đối phó hạm đội Nam Hán đi vào cửa sông Bạch Đằng — một tuyến thủy hiểm yếu nối biển với đồng bằng."},{"kicker":"Bước ngoặt","title":"Cọc gỗ, thủy triều và trận phục kích","text":"Theo truyền thống sử học và các nghiên cứu về chiến trường, Ngô Quyền bố trí cọc dưới lòng sông, lợi dụng thủy triều để nhử hạm đội đối phương tiến sâu rồi phản kích khi nước rút. Địa hình cửa sông, thời điểm con nước và phối hợp giữa thủy quân với lực lượng ven bờ biến Bạch Đằng thành một trận đánh quyết định."},{"kicker":"Hệ quả","title":"Xưng vương và trở lại Cổ Loa","text":"Sau chiến thắng, Ngô Quyền xưng vương và chọn Cổ Loa làm kinh đô. Việc trở lại một trung tâm gắn với Âu Lạc tạo biểu tượng mạnh về nối lại quốc thống, nhưng nhà Ngô chưa kịp xây dựng cơ chế kế vị ổn định nên nhanh chóng rơi vào tranh chấp sau khi ông mất."}],"transition":"Sự tan rã quyền lực nhà Ngô dẫn tới thời Thập nhị sứ quân; chính cuộc phân liệt ấy tạo sân khấu cho Đinh Bộ Lĩnh thống nhất đất nước và lập Đại Cồ Việt.","note":""},{"title":"Đinh Bộ Lĩnh: từ cát cứ đến Đại Cồ Việt","lead":"Sau cái chết của Ngô Quyền và những cuộc tranh chấp kế vị, quyền lực trung ương suy yếu nghiêm trọng. Đinh Bộ Lĩnh nổi lên từ Hoa Lư, lần lượt khuất phục các sứ quân và xây dựng một triều đình có tham vọng tập trung quyền lực.","scenes":[{"kicker":"Bối cảnh","title":"Hoa Lư: địa hình là một phần của chiến lược","text":"Vùng núi đá vôi, sông ngòi và thung lũng Hoa Lư tạo thành một không gian phòng thủ tự nhiên. Đinh Bộ Lĩnh dùng căn cứ này để tích lũy lực lượng; khảo cổ và di tích cho thấy Hoa Lư sau đó phát triển thành một kinh đô quân sự, cung điện và nghi lễ của triều đình mới."},{"kicker":"Bước ngoặt","title":"Dẹp các sứ quân và xưng Hoàng đế","text":"Đến năm 968, Đinh Bộ Lĩnh xưng Hoàng đế, đặt quốc hiệu Đại Cồ Việt và tổ chức triều nghi. Việc dùng đế hiệu thể hiện tuyên bố chủ quyền mạnh mẽ, trong khi quan hệ ngoại giao với nhà Tống vẫn được xử lý linh hoạt để tránh một cuộc đối đầu không cần thiết."},{"kicker":"Hệ quả","title":"Khủng hoảng kế vị đến quá nhanh","text":"Năm 979, Đinh Tiên Hoàng và con trưởng Đinh Liễn bị ám sát. Người kế vị còn nhỏ trong lúc nguy cơ quân Tống gia tăng, khiến triều đình chuyển quyền thực tế cho Lê Hoàn — một quyết định làm kết thúc nhà Đinh nhưng bảo toàn nhà nước vừa thống nhất."}],"transition":"Từ cuộc khủng hoảng ấy, Lê Hoàn bước lên ngôi, mở nhà Tiền Lê và phải đối mặt ngay với thử thách quân sự từ phương Bắc.","note":""},{"title":"Lê Đại Hành: một triều đại sinh ra trong tình trạng khẩn cấp","lead":"Nhà Tiền Lê ra đời khi Đại Cồ Việt vừa mất vua, người kế vị còn nhỏ và nhà Tống chuẩn bị can thiệp. Vì thế câu chuyện của Lê Hoàn bắt đầu bằng vấn đề sống còn: liệu nhà nước non trẻ có giữ được nền độc lập vừa giành lại hay không?","scenes":[{"kicker":"Bối cảnh","title":"Từ nhiếp chính đến hoàng đế","text":"Lê Hoàn vốn là Thập đạo tướng quân và nắm lực lượng quân sự chủ chốt. Trước nguy cơ xâm lược, ông được đưa lên ngôi năm 980; quyết định này gây tranh luận về tính chính danh nhưng đồng thời tạo ra một trung tâm chỉ huy thống nhất trong thời điểm chiến tranh cận kề."},{"kicker":"Bước ngoặt","title":"Kháng chiến chống Tống năm 981","text":"Quân Tống tiến vào cả đường bộ và đường thủy. Lê Hoàn tổ chức phòng thủ và phản công, buộc đối phương rút lui. Chiến thắng giúp Đại Cồ Việt củng cố vị thế đối ngoại và chứng minh rằng nền độc lập sau Bạch Đằng không còn chỉ dựa vào một cá nhân hay một trận đánh duy nhất."},{"kicker":"Hệ quả","title":"Quan hệ với Champa và khủng hoảng sau khi vua mất","text":"Triều Tiền Lê cũng can dự mạnh ở phía nam, trong đó có chiến dịch đánh Champa năm 982. Nhưng sau khi Lê Hoàn mất, các hoàng tử tranh ngôi khiến triều đình suy yếu, tạo điều kiện cho Lý Công Uẩn được tôn lên làm vua năm 1009."}],"transition":"Nhà Lý kế thừa một nhà nước đã đứng vững trước ngoại xâm nhưng cần một trung tâm chính trị rộng mở hơn Hoa Lư; câu trả lời sẽ là việc dời đô ra Thăng Long.","note":""},{"title":"Nhà Lý: đưa trung tâm quyền lực ra Thăng Long","lead":"Triều Lý kéo dài hơn hai thế kỷ và đặt nhiều nền móng cho nhà nước Đại Việt. Câu chuyện trung tâm là sự chuyển từ kinh đô phòng thủ Hoa Lư sang một đô thị đồng bằng lớn, rồi từ đó xây dựng bộ máy, tôn giáo và quân sự có tầm khu vực.","scenes":[{"kicker":"Bối cảnh","title":"Năm 1010: rời Hoa Lư","text":"Lý Công Uẩn quyết định dời đô ra thành Đại La và đổi tên thành Thăng Long. Trong Chiếu dời đô, lựa chọn mới được lý giải bằng vị trí thuận lợi, đất rộng bằng phẳng và khả năng phát triển lâu dài — một sự chuyển hướng từ căn cứ núi đá sang trung tâm châu thổ."},{"kicker":"Bước ngoặt","title":"Đại Việt vừa xây nhà nước vừa chiến đấu","text":"Nhà Lý phát triển Phật giáo, xây dựng văn miếu–giáo dục và củng cố hệ thống hành chính. Đối ngoại, chiến tranh với nhà Tống 1075–1077 và hoạt động của Lý Thường Kiệt cho thấy triều đình đã có khả năng huy động quân đội quy mô lớn; phía nam, mốc 1069 mở rộng kiểm soát tới ba châu mới."},{"kicker":"Hệ quả","title":"Từ thịnh trị đến vấn đề kế vị","text":"Cuối triều Lý, tài chính, quyền lực quý tộc và đấu tranh trong cung đình làm nhà nước suy yếu. Họ Trần, xuất thân từ một thế lực ven biển–sông nước, dần nắm quân đội và triều chính rồi tổ chức việc chuyển ngôi năm 1225."}],"transition":"Nhà Trần kế thừa Thăng Long và phần lớn thiết chế của nhà Lý, nhưng sẽ phải đối mặt với thử thách quân sự lớn hơn hẳn: ba cuộc chiến với đế chế Mông–Nguyên.","note":""},{"title":"Nhà Trần: ba lần chống Mông–Nguyên và một đế chế học cách sống sót","lead":"Thế kỷ XIII đặt Đại Việt trước một sức ép chưa từng có: các đội quân Mông Cổ và nhà Nguyên đã chinh phục phần lớn lục địa Á–Âu. Nhà Trần sống sót nhờ sự linh hoạt chiến lược, khả năng rút bỏ kinh thành và khai thác địa hình, hậu cần.","scenes":[{"kicker":"Bối cảnh","title":"Một triều đại dựa trên mạng lưới hoàng tộc","text":"Nhà Trần tổ chức quyền lực thông qua quan hệ họ tộc, chế độ Thái thượng hoàng và các thái ấp. Cấu trúc này vừa tạo sự gắn kết của tầng lớp chỉ huy vừa tiềm ẩn cạnh tranh nội bộ, nhưng trong chiến tranh nó giúp huy động nhiều trung tâm quân sự dưới một chiến lược chung."},{"kicker":"Bước ngoặt","title":"1285 và 1288: không giữ đất bằng mọi giá","text":"Trước quân Nguyên, triều Trần nhiều lần bỏ Thăng Long, thực hiện tiêu thổ và kéo dài chiến tranh cho đến khi đối phương thiếu lương. Năm 1288, đoàn thuyền lương bị đánh ở Vân Đồn và trận Bạch Đằng dùng bãi cọc cùng thủy triều để đánh tan thủy quân rút lui của Ô Mã Nhi."},{"kicker":"Hệ quả","title":"Hòa bình, mở rộng phía nam và suy yếu cuối thế kỷ XIV","text":"Sau chiến tranh, Đại Việt bước vào giai đoạn phục hồi. Năm 1306, việc tiếp nhận Châu Ô và Châu Lý làm thay đổi biên giới phía nam. Nhưng đến cuối thế kỷ XIV, khủng hoảng tài chính, chiến tranh với Champa và đấu tranh quyền lực tạo không gian cho Hồ Quý Ly cải cách rồi thay triều."}],"transition":"Những cải cách quyết liệt của Hồ Quý Ly nhằm cứu một trật tự đang khủng hoảng, nhưng việc thay nhà Trần làm suy giảm tính chính danh đúng lúc nhà Minh chuẩn bị can thiệp.","note":""},{"title":"Nhà Hồ: cải cách nhanh hơn khả năng tạo đồng thuận","lead":"Hồ Quý Ly là một trong những nhân vật gây tranh luận nhất lịch sử trung đại Việt Nam. Ông nhìn thấy nhiều vấn đề thực của cuối Trần và tiến hành cải cách mạnh, nhưng triều đại quá ngắn để các thay đổi ổn định trước cuộc xâm lược của nhà Minh.","scenes":[{"kicker":"Bối cảnh","title":"Tây Đô và một chương trình cải cách lớn","text":"Hồ Quý Ly xây Tây Đô ở Thanh Hóa, phát hành tiền giấy, thay đổi thuế và ruộng đất, tổ chức lại giáo dục và quân sự. Nhiều chính sách nhằm hạn chế thế lực quý tộc và tăng nguồn lực cho nhà nước, song tốc độ thay đổi và việc chuyển triều tạo phản ứng mạnh."},{"kicker":"Bước ngoặt","title":"Khủng hoảng chính danh gặp sức ép từ phương Bắc","text":"Việc phế nhà Trần tạo cho nhà Minh một lý do chính trị để can thiệp dưới danh nghĩa “phù Trần”. Trong thực tế, chiến dịch 1406–1407 nhanh chóng biến thành cuộc chinh phục toàn diện; hệ thống phòng thủ nhà Hồ sụp đổ dù có thành lũy và quân đội đáng kể."},{"kicker":"Hệ quả","title":"Đại Ngu bị xóa tên khỏi bản đồ chính trị","text":"Sau thất bại, nhà Minh đặt lại Giao Chỉ và đưa khu vực vào hệ thống hành chính trực tiếp. Nhiều sách vở, nhân lực và tài nguyên bị chuyển đi; đồng thời các cuộc kháng chiến nổ ra liên tiếp, chuẩn bị bối cảnh cho phong trào Lam Sơn."}],"transition":"Thời thuộc Minh chỉ kéo dài hai thập kỷ nhưng để lại tác động sâu. Chính trong giai đoạn này, Lê Lợi và Nguyễn Trãi xây dựng một phong trào kháng chiến có khả năng chuyển từ căn cứ địa phương thành chiến tranh giải phóng toàn quốc.","note":""},{"title":"Thuộc Minh và Lam Sơn: từ một căn cứ nhỏ đến bao vây Đông Quan","lead":"Sau 1407, nhà Minh tổ chức Giao Chỉ như một đơn vị hành chính của đế chế. Kháng cự diễn ra ở nhiều nơi, nhưng cuộc khởi nghĩa Lam Sơn từ năm 1418 mới tạo ra lực lượng đủ bền để thay đổi cục diện.","scenes":[{"kicker":"Bối cảnh","title":"Những năm đầu ở Lam Sơn","text":"Lê Lợi khởi nghĩa tại Thanh Hóa trong điều kiện thiếu lương, bị truy kích và nhiều lần phải rút vào vùng núi. Sự tồn tại qua những năm đầu khó khăn là bước quan trọng: lực lượng Lam Sơn học cách dựa vào địa hình, mạng lưới địa phương và khả năng xây dựng liên minh."},{"kicker":"Bước ngoặt","title":"Mở rộng vào Nghệ An rồi tiến ra Bắc","text":"Từ giữa thập niên 1420, nghĩa quân chuyển hướng chiến lược vào Nghệ An, tạo được vùng hậu phương rộng hơn rồi tiến ra đồng bằng Bắc Bộ. Nguyễn Trãi đóng vai trò lớn trong ngoại giao và chiến tranh tâm lý, kết hợp quân sự với thư từ dụ hàng."},{"kicker":"Hệ quả","title":"Chi Lăng–Xương Giang và Hội thề Đông Quan","text":"Năm 1427, viện binh Minh bị đánh bại trong các chiến dịch lớn; Vương Thông ở Đông Quan chấp nhận thương lượng. Hội thề Đông Quan khép lại chiến tranh, quân Minh rút về nước và Lê Lợi lên ngôi năm 1428."}],"transition":"Chiến thắng Lam Sơn tạo nhà Lê sơ. Thách thức kế tiếp không còn là đuổi quân chiếm đóng mà là xây dựng một nhà nước có luật pháp, quan liêu, thuế khóa và trật tự kế vị ổn định.","note":""},{"title":"Lê sơ: từ khởi nghĩa thắng lợi đến nhà nước Hồng Đức","lead":"Thế kỷ XV là một trong những giai đoạn nhà nước quân chủ Đại Việt tập trung mạnh nhất. Từ nền tảng của Lê Lợi, triều đình dần xây dựng bộ máy quan liêu, pháp luật và quân sự rộng khắp, đạt đỉnh dưới Lê Thánh Tông.","scenes":[{"kicker":"Bối cảnh","title":"Từ Bình Định Vương đến Lê Thái Tổ","text":"Năm 1428, Lê Lợi lên ngôi ở Đông Kinh. Triều đình phải giải quyết hậu quả hai thập kỷ chiến tranh, tưởng thưởng công thần, phục hồi sản xuất và xác lập quan hệ ngoại giao với nhà Minh trong khi khẳng định nền độc lập."},{"kicker":"Bước ngoặt","title":"Lê Thánh Tông và trật tự Hồng Đức","text":"Dưới Lê Thánh Tông, bộ máy hành chính được tổ chức chặt chẽ hơn, giáo dục Nho học và khoa cử phát triển, luật pháp được hệ thống hóa. Nhà nước đồng thời đẩy mạnh khảo sát, quản lý địa phương và quân đội, làm cho quyền lực trung ương thâm nhập sâu hơn vào các vùng."},{"kicker":"Hệ quả","title":"1471 và một thay đổi lớn ở miền Trung","text":"Chiến dịch 1471 đánh bại Vijaya của Champa và dẫn tới việc tổ chức Quảng Nam thừa tuyên, làm thay đổi lâu dài bản đồ chính trị miền Trung. Sau thời Lê Thánh Tông, tranh chấp cung đình và các vua ngắn triều khiến quyền lực suy yếu, tạo cơ hội cho Mạc Đăng Dung."}],"transition":"Năm 1527, nhà Mạc thay nhà Lê tại Thăng Long. Nhưng thay vì một cuộc chuyển triều dứt khoát, Đại Việt bước vào nhiều thập kỷ có hai trung tâm chính thống cạnh tranh.","note":""},{"title":"Nam–Bắc triều: khi “chính thống” có hai kinh đô","lead":"Từ 1527, nhà Mạc kiểm soát kinh đô và phần lớn miền Bắc, trong khi các lực lượng trung thành với nhà Lê phục dựng triều đình ở Thanh Hóa. Cuộc chiến không có một đường biên cố định mà là quá trình giằng co lâu dài giữa các vùng và mạng lưới quân sự.","scenes":[{"kicker":"Bối cảnh","title":"Mạc Đăng Dung thay triều","text":"Xuất thân từ quân đội và triều chính cuối Lê sơ, Mạc Đăng Dung lên ngôi năm 1527. Nhà Mạc nhanh chóng xây dựng triều đình riêng, tổ chức khoa cử và duy trì đời sống kinh tế, nhưng phải đối mặt với vấn đề chính danh vì lực lượng phục Lê không biến mất."},{"kicker":"Bước ngoặt","title":"Lê trung hưng hình thành ở Thanh Hóa","text":"Nguyễn Kim và sau đó Trịnh Kiểm tổ chức lực lượng tôn vua Lê, tạo một trung tâm đối nghịch ở phía nam. Chiến tranh kéo dài hàng chục năm, với các thành, đường sông và vùng đồng bằng liên tục đổi chủ; vì thế atlas dùng vùng kiểm soát chứ không vẽ hai “quốc gia” cứng."},{"kicker":"Hệ quả","title":"1592 không phải là kết thúc hoàn toàn","text":"Quân Lê–Trịnh chiếm lại Thăng Long năm 1592, nhà Mạc rút lên vùng Cao Bằng và tiếp tục tồn tại thêm nhiều thập kỷ dưới những hình thức khác nhau. Trong khi đó, quyền lực thực tế của họ Trịnh ở phía bắc ngày càng lớn, còn họ Nguyễn bắt đầu tạo căn cứ riêng ở Thuận Hóa."}],"transition":"Sự phân hóa từ thời Nam–Bắc triều phát triển thành cấu trúc Trịnh–Nguyễn: cùng tôn vua Lê về danh nghĩa nhưng hai tập đoàn xây dựng hai không gian chính trị ngày càng khác biệt.","note":""},{"title":"Trịnh–Nguyễn: một đất nước danh nghĩa, hai hệ thống quyền lực","lead":"Từ thế kỷ XVII, vua Lê vẫn là biểu tượng chính thống nhưng quyền lực thực tế chia giữa chúa Trịnh ở Đàng Ngoài và chúa Nguyễn ở Đàng Trong. Đây vừa là thời chiến kéo dài, vừa là thời mở rộng thương mại và biến đổi bản đồ phía nam.","scenes":[{"kicker":"Bối cảnh","title":"Nguyễn Hoàng đi vào Thuận Hóa","text":"Từ năm 1558, Nguyễn Hoàng xây dựng căn cứ ở Thuận Hóa rồi Quảng Nam. Qua nhiều thập kỷ, chính quyền họ Nguyễn phát triển mạng lưới quân sự, thuế khóa và thương mại riêng, dựa nhiều vào các cảng như Hội An và quan hệ với thương nhân Nhật Bản, Trung Hoa, châu Âu."},{"kicker":"Bước ngoặt","title":"Chiến tranh Trịnh–Nguyễn và tuyến sông Gianh","text":"Từ 1627 đến 1672, hai bên giao chiến nhiều đợt mà không thể tiêu diệt nhau. Hệ thống lũy ở Quảng Bình và tuyến sông Gianh trở thành vùng phân chia trên thực tế; sau khi đình chiến, hai miền sống trong trạng thái riêng biệt hơn một thế kỷ."},{"kicker":"Hệ quả","title":"Nam tiến và hình thành Gia Định","text":"Trong lúc chiến tuyến phía bắc ổn định, chúa Nguyễn mở rộng quản trị xuống Phú Yên, Khánh Hòa, vùng Đông Nam Bộ và đồng bằng sông Cửu Long. Năm 1698, Nguyễn Hữu Cảnh tổ chức phủ Gia Định; đến giữa thế kỷ XVIII, không gian Đàng Trong đã khác căn bản so với đầu thế kỷ XVII."}],"transition":"Sự mở rộng nhanh đi cùng thuế khóa, cạnh tranh thương mại và bất mãn xã hội. Từ vùng Tây Sơn ở Bình Định, một cuộc nổi dậy sẽ phá vỡ cả chính quyền Nguyễn lẫn trật tự Trịnh–Lê.","note":""},{"title":"Tây Sơn: cuộc nổi dậy địa phương làm rung chuyển cả Đại Việt","lead":"Phong trào Tây Sơn bắt đầu ở miền Trung nhưng chỉ trong hai thập kỷ đã lật đổ các thế lực Nguyễn, Trịnh và làm thay đổi triều Lê. Bản đồ giai đoạn này phải luôn chuyển động vì quyền kiểm soát thay đổi theo từng chiến dịch.","scenes":[{"kicker":"Bối cảnh","title":"Ba anh em Tây Sơn và cuộc nổi dậy 1771","text":"Nguyễn Nhạc, Nguyễn Huệ và Nguyễn Lữ xây dựng lực lượng ở vùng Tây Sơn, khai thác bất mãn với thuế khóa và bộ máy địa phương. Phong trào nhanh chóng mở rộng xuống Quy Nhơn và phía nam, làm chính quyền chúa Nguyễn tan rã."},{"kicker":"Bước ngoặt","title":"Rạch Gầm–Xoài Mút rồi tiến ra Bắc","text":"Năm 1785, Nguyễn Huệ đánh bại quân Xiêm tại Rạch Gầm–Xoài Mút trong một trận thủy chiến lớn. Năm 1786, quân Tây Sơn tiến ra Thăng Long, lật đổ quyền lực họ Trịnh; cấu trúc chính trị tồn tại hơn hai thế kỷ bị phá vỡ chỉ trong vài chiến dịch."},{"kicker":"Hệ quả","title":"Ngọc Hồi–Đống Đa và cuộc đua với Nguyễn Ánh","text":"Đầu năm 1789, Quang Trung đánh bại quân Thanh tiến vào Thăng Long. Tuy nhiên, sau khi ông mất năm 1792, nội bộ Tây Sơn suy yếu trong khi Nguyễn Ánh, với căn cứ ngày càng vững ở Gia Định, từng bước tiến ra miền Trung và Bắc."}],"transition":"Năm 1802, Nguyễn Ánh đánh bại Tây Sơn, lên ngôi Gia Long và lần đầu cai quản một lãnh thổ liên tục từ biên giới Trung Hoa đến đồng bằng sông Cửu Long dưới một triều đình.","note":""},{"title":"Triều Nguyễn: thống nhất lãnh thổ, tập trung hóa nhà nước và sức ép phương Tây","lead":"Đầu thế kỷ XIX, triều Nguyễn cai quản một không gian bắc–nam chưa từng được đặt lâu dài dưới cùng một triều đình theo hình dạng đó. Huế trở thành kinh đô của một nhà nước vừa kế thừa truyền thống Đại Việt vừa phải quản trị miền Nam mới tích hợp.","scenes":[{"kicker":"Bối cảnh","title":"Gia Long và việc nối lại một đất nước sau nội chiến","text":"Sau chiến thắng năm 1802, Gia Long tổ chức lại hệ thống hành chính, xây dựng kinh đô Huế và cố gắng cân bằng các vùng từng thuộc Đàng Ngoài, Tây Sơn và Gia Định. Mạng lưới đường trạm, thành lũy và quan lại giúp liên kết lãnh thổ dài hẹp hơn trước."},{"kicker":"Bước ngoặt","title":"Minh Mạng tập trung hóa sâu hơn","text":"Dưới Minh Mạng, các tổng trấn lớn bị bãi bỏ và hệ thống tỉnh được tổ chức tương đối thống nhất. Triều đình thúc đẩy Nho học và quan liêu, đồng thời can dự mạnh vào Lào, Campuchia và quản lý biển đảo; tuy vậy ảnh hưởng và chủ quyền phải được phân biệt rõ khi dựng bản đồ."},{"kicker":"Hệ quả","title":"Từ Đà Nẵng 1858 đến các hiệp ước bảo hộ","text":"Sức ép quân sự Pháp–Tây Ban Nha bắt đầu bằng cuộc tấn công Đà Nẵng năm 1858 rồi chuyển trọng tâm vào Nam Kỳ. Trong vài thập kỷ, các hiệp ước và chiến dịch quân sự làm triều Nguyễn mất quyền kiểm soát ngày càng lớn, kết thúc bằng chế độ bảo hộ cuối thế kỷ XIX."}],"transition":"Từ đây bản đồ Việt Nam không còn là một màu triều Nguyễn: Nam Kỳ là thuộc địa, Bắc Kỳ và Trung Kỳ có các chế độ bảo hộ khác nhau trong cấu trúc Đông Dương thuộc Pháp.","note":""},{"title":"Thời Pháp thuộc: ba xứ, một không gian thuộc địa và nhiều phong trào đối kháng","lead":"Từ cuối thế kỷ XIX đến 1945, Việt Nam nằm trong Liên bang Đông Dương nhưng được quản trị qua ba chế độ khác nhau: Bắc Kỳ, Trung Kỳ và Nam Kỳ. Đây là thời kỳ đô thị hóa, khai thác thuộc địa và cũng là thời kỳ xuất hiện nhiều dòng tư tưởng quốc gia mới.","scenes":[{"kicker":"Bối cảnh","title":"Đường sắt, đồn điền và các đô thị thuộc địa","text":"Chính quyền Pháp xây đường sắt, cảng, hệ thống thuế và cơ sở hành chính phục vụ nhà nước thuộc địa và nền kinh tế xuất khẩu. Hà Nội, Hải Phòng và Sài Gòn phát triển nhanh, trong khi đồn điền cao su, khai mỏ và thuế nông thôn tạo những biến đổi xã hội sâu sắc."},{"kicker":"Bước ngoặt","title":"Từ Cần Vương đến các tổ chức quốc gia và cộng sản","text":"Kháng chiến chống Pháp trải qua nhiều hình thức: phong trào Cần Vương, các nhà cải cách như Phan Châu Trinh, hoạt động của Phan Bội Châu, Việt Nam Quốc dân đảng và phong trào cộng sản. Những lực lượng này khác nhau về mục tiêu và phương pháp nhưng đều góp phần đặt vấn đề tương lai chính trị của đất nước."},{"kicker":"Hệ quả","title":"Chiến tranh thế giới thứ hai làm hệ thống thuộc địa lung lay","text":"Nhật Bản hiện diện quân sự ở Đông Dương từ 1940 trong khi chính quyền Pháp Vichy vẫn vận hành phần lớn bộ máy cho tới cuộc đảo chính tháng 3/1945. Khi Nhật đầu hàng Đồng Minh tháng 8, khoảng trống quyền lực xuất hiện rất nhanh trên toàn Đông Dương."}],"transition":"Khoảng trống tháng 8/1945 cho phép Việt Minh phát động giành chính quyền ở nhiều địa phương, Bảo Đại thoái vị và nước Việt Nam Dân chủ Cộng hòa được tuyên bố ở Hà Nội.","note":""},{"title":"Tháng Tám 1945: vài tuần làm thay đổi cả hệ thống chính trị","lead":"Năm 1945 không phải một trạng thái ổn định mà là chuỗi chuyển tiếp dồn dập: Nhật đảo chính Pháp, Nhật đầu hàng, Việt Minh giành chính quyền, triều Nguyễn kết thúc và một nhà nước cộng hòa được tuyên bố.","scenes":[{"kicker":"Bối cảnh","title":"Tháng 3 đến tháng 8: quyền lực thuộc địa vỡ vụn","text":"Sau cuộc đảo chính ngày 9/3/1945, Nhật loại bộ máy quân sự Pháp và chính phủ Trần Trọng Kim hoạt động dưới triều Bảo Đại trong vài tháng. Đến giữa tháng 8, việc Nhật đầu hàng tạo ra một khoảng trống mới trước khi lực lượng Đồng Minh vào Đông Dương giải giáp quân Nhật."},{"kicker":"Bước ngoặt","title":"Cách mạng tháng Tám và sự chuyển giao tại Huế","text":"Việt Minh và các lực lượng địa phương giành chính quyền tại Hà Nội và nhiều tỉnh, rồi tại Huế Bảo Đại tuyên bố thoái vị. Việc trao ấn kiếm trở thành biểu tượng cho sự kết thúc của triều Nguyễn, dù trên thực tế quyền lực ở các địa phương không chuyển giao theo một kịch bản đồng nhất."},{"kicker":"Hệ quả","title":"2/9/1945 và những thách thức lập tức xuất hiện","text":"Hồ Chí Minh đọc Tuyên ngôn Độc lập tại Ba Đình, tuyên bố thành lập Việt Nam Dân chủ Cộng hòa. Nhưng nhà nước mới ngay lập tức phải đối mặt với nạn đói, tài chính yếu, quân Đồng Minh vào giải giáp và câu hỏi Pháp có trở lại Đông Dương hay không."}],"transition":"Những cuộc thương lượng năm 1946 không ngăn được xung đột leo thang. Đến cuối năm, chiến tranh giữa Pháp và Việt Nam Dân chủ Cộng hòa bùng nổ trên quy mô toàn quốc.","note":""},{"title":"Chiến tranh Đông Dương: từ chiến tranh đô thị đến Điện Biên Phủ","lead":"Cuộc chiến 1946–1954 thay đổi từ những trận đánh ở đô thị sang chiến tranh dài ngày ở nông thôn và biên giới. Cả hai bên đều tìm cách xây dựng nhà nước, quân đội và hậu phương trong khi bối cảnh Chiến tranh Lạnh làm cuộc chiến ngày càng quốc tế hóa.","scenes":[{"kicker":"Bối cảnh","title":"Hà Nội cuối năm 1946 và chiến lược trường kỳ","text":"Sau xung đột leo thang, giao tranh lớn nổ ra tại Hà Nội tháng 12/1946. Lực lượng Việt Minh rút dần về căn cứ, lựa chọn chiến tranh lâu dài thay vì cố giữ các thành phố trước ưu thế hỏa lực của Pháp."},{"kicker":"Bước ngoặt","title":"Năm 1950 làm cán cân thay đổi","text":"Sau thắng lợi của Cách mạng Trung Quốc, Việt Minh có điều kiện tiếp cận biên giới và nguồn viện trợ lớn hơn; Chiến dịch Biên giới 1950 giúp mở hành lang phía bắc. Phía Pháp đồng thời tăng cường Quốc gia Việt Nam và nhận hỗ trợ ngày càng lớn từ Hoa Kỳ."},{"kicker":"Hệ quả","title":"Kế hoạch Navarre dẫn tới Điện Biên Phủ","text":"Đến 1953, Pháp tìm kiếm một trận địa có thể buộc đối phương giao chiến trong điều kiện thuận lợi. Việc xây tập đoàn cứ điểm Điện Biên Phủ lại tạo cơ hội cho Việt Minh tập trung pháo binh, hậu cần và lực lượng quanh thung lũng; trận đánh quyết định diễn ra đầu năm 1954."}],"transition":"Thất bại của Pháp tại Điện Biên Phủ đưa các bên tới Geneva, nơi một thỏa thuận đình chiến và các vùng tập kết quân sự tạm thời được xác lập.","note":""},{"title":"Geneva 1954: một đường quân sự tạm thời trở thành đường chia cắt lâu dài","lead":"Geneva không tạo ra hai quốc gia bằng một điều khoản đơn giản. Hiệp định đình chiến quy định một giới tuyến quân sự tạm thời và vùng phi quân sự để hai bên tập kết lực lượng sau chiến tranh, trong khi tương lai chính trị được để lại cho một tiến trình khác.","scenes":[{"kicker":"Bối cảnh","title":"Điện Biên Phủ thay đổi vị thế đàm phán","text":"Khi hội nghị Geneva đang diễn ra, tập đoàn cứ điểm Điện Biên Phủ thất thủ ngày 7/5/1954. Kết quả quân sự này làm rõ rằng Pháp không thể tiếp tục chiến tranh theo cách cũ và đẩy nhanh nỗ lực tìm một thỏa thuận ngừng bắn."},{"kicker":"Bước ngoặt","title":"Giới tuyến và thời hạn tập kết","text":"Hiệp định ngày 20/7 quy định lực lượng Quân đội Nhân dân Việt Nam tập kết về phía bắc và lực lượng Liên hiệp Pháp về phía nam của giới tuyến quân sự tạm thời, kèm vùng phi quân sự hai bên. Việc di chuyển lực lượng được ấn định hoàn tất trong tối đa 300 ngày."},{"kicker":"Hệ quả","title":"Tạm thời về pháp lý, lâu dài trong thực tế","text":"Tuyên bố cuối cùng của hội nghị coi giới tuyến không phải là biên giới chính trị và đề cập tổng tuyển cử trong tương lai. Tuy nhiên, các bên liên quan có lập trường khác nhau về văn kiện và việc thực hiện, khiến sự phân chia quân sự phát triển thành hai hệ thống chính trị đối nghịch."}],"transition":"Từ 1955, miền Bắc và miền Nam hình thành những nhà nước, liên minh và chiến lược khác nhau. Atlas vì vậy chuyển sang bản đồ hai miền thay vì kéo dài cách tô vùng tập kết của năm 1954.","note":""},{"title":"Hai miền Việt Nam: chiến tranh trong một thế giới Chiến tranh Lạnh","lead":"Giai đoạn 1955–1974 phải được đọc đồng thời ở nhiều cấp: hai chính quyền Việt Nam, phong trào nổi dậy ở miền Nam, sự can dự ngày càng lớn của Hoa Kỳ, hỗ trợ từ Liên Xô và Trung Quốc cho miền Bắc, cùng một cuộc chiến có tác động xã hội rất sâu rộng.","scenes":[{"kicker":"Bối cảnh","title":"Hai hệ thống chính trị hình thành","text":"Ở miền Bắc, Việt Nam Dân chủ Cộng hòa tập trung tái thiết và xây dựng mô hình xã hội chủ nghĩa. Ở miền Nam, Việt Nam Cộng hòa hình thành dưới Ngô Đình Diệm rồi trải qua nhiều biến động chính trị sau 1963. Cả hai đều tuyên bố tính chính danh đối với tương lai của Việt Nam."},{"kicker":"Bước ngoặt","title":"Leo thang chiến tranh và Tết Mậu Thân","text":"Từ giữa thập niên 1960, quân chiến đấu Hoa Kỳ hiện diện với quy mô lớn trong khi chiến tranh trên không và trên bộ mở rộng. Cuộc Tổng tiến công Tết Mậu Thân 1968 gây tổn thất rất lớn và không đạt mọi mục tiêu quân sự của phía tiến công, nhưng tác động mạnh đến nhận thức chính trị và chiến lược của Hoa Kỳ."},{"kicker":"Hệ quả","title":"Paris 1973 không chấm dứt chiến sự","text":"Hiệp định Paris dẫn tới việc rút phần lớn lực lượng chiến đấu Hoa Kỳ và trao trả tù binh, nhưng giao tranh giữa các lực lượng Việt Nam tiếp tục. Đến 1974, cán cân quân sự và nguồn hỗ trợ bên ngoài thay đổi rõ rệt, chuẩn bị cho chiến dịch quyết định năm 1975."}],"transition":"Đầu 1975, những thắng lợi nhanh ở Tây Nguyên và miền Trung làm hệ thống phòng thủ của Việt Nam Cộng hòa sụp đổ nhanh hơn dự đoán, dẫn tới trận cuối cùng ở Sài Gòn.","note":""},{"title":"1975: từ Buôn Ma Thuột đến Sài Gòn trong chưa đầy hai tháng","lead":"Năm 1975 là một chuỗi biến động quân sự cực nhanh. Bản đồ không nên tô cả năm bằng một trạng thái duy nhất: quyền kiểm soát thay đổi tuần này qua tuần khác từ Tây Nguyên xuống duyên hải rồi tới Sài Gòn.","scenes":[{"kicker":"Bối cảnh","title":"Buôn Ma Thuột phá vỡ thế cân bằng","text":"Tháng 3/1975, cuộc tiến công vào Buôn Ma Thuột tạo ra một đột phá chiến lược. Quyết định rút khỏi Tây Nguyên và những khó khăn trong tổ chức rút quân làm hệ thống phòng thủ miền Trung suy sụp nhanh, kéo theo Huế và Đà Nẵng."},{"kicker":"Bước ngoặt","title":"Chiến dịch cuối cùng hướng về Sài Gòn","text":"Sau khi miền Trung thất thủ, lực lượng phía Bắc và Mặt trận tăng tốc chuẩn bị cho cuộc tiến công cuối cùng. Các hướng quân sự hội tụ quanh Sài Gòn trong khi chính quyền Việt Nam Cộng hòa trải qua thay đổi lãnh đạo và nỗ lực tìm một lối thoát chính trị."},{"kicker":"Hệ quả","title":"30/4 và kết thúc chiến tranh","text":"Ngày 30/4/1975, lực lượng cách mạng tiến vào trung tâm Sài Gòn và chính quyền Việt Nam Cộng hòa chấm dứt. Chiến tranh kết thúc, nhưng quá trình thống nhất về mặt nhà nước và xây dựng một hệ thống quản trị chung tiếp tục sang năm 1976."}],"transition":"Năm 1976, Quốc hội quyết định thống nhất nhà nước với tên Cộng hòa Xã hội Chủ nghĩa Việt Nam. Giai đoạn hậu chiến sau đó đối mặt những bài toán kinh tế, xã hội và an ninh khu vực rất khó khăn.","note":""},{"title":"1976–1985: thống nhất nhà nước nhưng hòa bình chưa đồng nghĩa ổn định","lead":"Sau ba thập kỷ chiến tranh, Việt Nam bước vào hòa bình với cơ sở hạ tầng bị tàn phá, nền kinh tế thiếu thốn và nhiệm vụ hợp nhất hai hệ thống quản trị khác nhau. Đồng thời, môi trường an ninh ở biên giới Tây Nam và phía Bắc nhanh chóng xấu đi.","scenes":[{"kicker":"Bối cảnh","title":"Thống nhất bộ máy và tái thiết hậu chiến","text":"Năm 1976, nhà nước thống nhất được thiết lập với thủ đô Hà Nội. Chính sách kinh tế kế hoạch hóa được mở rộng trong bối cảnh thiếu vốn, năng suất thấp và hậu quả chiến tranh nặng nề; đời sống thường nhật ở nhiều nơi gắn với tem phiếu và khan hiếm hàng hóa."},{"kicker":"Bước ngoặt","title":"Xung đột Campuchia và biên giới phía Bắc","text":"Cuối thập niên 1970, xung đột với Khmer Đỏ leo thang ở biên giới Tây Nam và quân Việt Nam tiến vào Campuchia cuối 1978. Tháng 2/1979, Trung Quốc mở cuộc chiến tranh biên giới phía Bắc; giao tranh lớn diễn ra trong thời gian ngắn nhưng căng thẳng kéo dài nhiều năm."},{"kicker":"Hệ quả","title":"Khó khăn kinh tế thúc đẩy thử nghiệm cải cách","text":"Đầu thập niên 1980, nhiều địa phương và ngành kinh tế bắt đầu thử các cơ chế khoán và nới lỏng kiểm soát để tăng sản xuất. Các thử nghiệm đó cho thấy mô hình quản lý cũ gặp giới hạn và chuẩn bị nền tảng thực tế cho bước ngoặt Đổi Mới năm 1986."}],"transition":"Đại hội VI năm 1986 chính thức hóa một chương trình cải cách rộng hơn, chuyển trọng tâm câu chuyện lịch sử từ tái thiết hậu chiến sang thay đổi cơ chế kinh tế và mở cửa đối ngoại.","note":""},{"title":"Đổi Mới: cải cách bắt đầu từ nhu cầu sống còn của nền kinh tế","lead":"Đổi Mới không diễn ra trong một ngày, nhưng Đại hội VI năm 1986 trở thành mốc biểu tượng cho việc thừa nhận cần thay đổi cách vận hành nền kinh tế. Trong thập niên sau đó, thị trường, hộ gia đình và doanh nghiệp có vai trò lớn hơn trong khi nhà nước vẫn giữ định hướng xã hội chủ nghĩa.","scenes":[{"kicker":"Bối cảnh","title":"Từ tem phiếu đến kinh tế hàng hóa","text":"Các cải cách nông nghiệp, giá cả và doanh nghiệp từng bước giảm cơ chế bao cấp trực tiếp. Sản xuất lương thực cải thiện rõ, thương mại tư nhân mở rộng và đô thị bắt đầu thay đổi nhanh; đồng thời quá trình chuyển đổi cũng tạo chênh lệch mới giữa vùng, ngành và nhóm dân cư."},{"kicker":"Bước ngoặt","title":"Mở cửa đối ngoại sau nhiều năm cô lập","text":"Việt Nam rút quân khỏi Campuchia, bình thường hóa quan hệ với Trung Quốc năm 1991, gia nhập ASEAN ngày 28/7/1995 và bình thường hóa quan hệ ngoại giao với Hoa Kỳ cùng năm. Những bước này tái định vị đất nước trong khu vực sau Chiến tranh Lạnh."},{"kicker":"Hệ quả","title":"Một nền kinh tế mới hình thành vào cuối thế kỷ","text":"Đến cuối thập niên 1990, đầu tư nước ngoài, xuất khẩu và khu vực tư nhân đã trở thành các bộ phận quan trọng của nền kinh tế. Khủng hoảng tài chính châu Á 1997 cho thấy hội nhập mang cả cơ hội lẫn rủi ro, nhưng hướng mở cửa nhìn chung được duy trì."}],"transition":"Bước sang thế kỷ XXI, câu hỏi không còn là có mở cửa hay không mà là hội nhập sâu đến mức nào — dẫn tới các hiệp định thương mại và việc gia nhập WTO năm 2007.","note":""},{"title":"2001–2015: từ mở cửa sang hội nhập sâu vào kinh tế thế giới","lead":"Giai đoạn đầu thế kỷ XXI chứng kiến Việt Nam gắn chặt hơn với chuỗi sản xuất, thương mại và các định chế quốc tế. Cùng với tăng trưởng là quá trình đô thị hóa nhanh, thay đổi cơ cấu việc làm và mở rộng hạ tầng.","scenes":[{"kicker":"Bối cảnh","title":"Công nghiệp hóa và các hành lang đô thị mới","text":"Các khu công nghiệp, cảng và mạng lưới giao thông phát triển quanh Hà Nội, Hải Phòng, TP.HCM, Đồng Nai, Bình Dương và miền Trung. Hàng triệu người di chuyển từ nông thôn đến các trung tâm sản xuất, làm thay đổi cấu trúc gia đình, lao động và không gian đô thị."},{"kicker":"Bước ngoặt","title":"Gia nhập WTO năm 2007","text":"Việt Nam trở thành thành viên thứ 150 của WTO ngày 11/1/2007 sau một quá trình đàm phán kéo dài. Mốc này đòi hỏi điều chỉnh nhiều quy định thương mại và củng cố vị trí của Việt Nam trong mạng lưới xuất khẩu toàn cầu."},{"kicker":"Hệ quả","title":"Hội nhập tạo cả cơ hội lẫn sức ép","text":"Tăng trưởng xuất khẩu và đầu tư nước ngoài đi cùng áp lực về hạ tầng, môi trường, năng suất và chất lượng quản trị. Tranh chấp trên Biển Đông cũng trở thành vấn đề nổi bật hơn, vì thế atlas tách lớp Hoàng Sa–Trường Sa khỏi đường bao đất liền thay vì tô một vùng biển đơn giản."}],"transition":"Từ giữa thập niên 2010, chuyển đổi số, chuỗi cung ứng công nghệ và cạnh tranh chiến lược ở châu Á trở thành những yếu tố ngày càng quan trọng đối với câu chuyện phát triển Việt Nam.","note":""},{"title":"2016–2026: một Việt Nam công nghiệp hơn, số hóa hơn và gắn với thế giới hơn","lead":"Thập niên gần đây kết hợp ba câu chuyện lớn: công nghiệp chế tạo và chuỗi cung ứng mở rộng, đời sống số đi sâu vào kinh tế–xã hội, và môi trường quốc tế biến động mạnh từ đại dịch đến cạnh tranh chiến lược.","scenes":[{"kicker":"Bối cảnh","title":"Chuỗi cung ứng và nền kinh tế số tăng tốc","text":"Điện tử, máy móc, dệt may và nhiều ngành xuất khẩu tiếp tục đóng vai trò lớn trong tăng trưởng, trong khi thương mại điện tử, thanh toán số và dịch vụ trực tuyến trở nên phổ biến hơn. Các đô thị lớn phải đồng thời xử lý áp lực giao thông, nhà ở, năng lượng và biến đổi khí hậu."},{"kicker":"Bước ngoặt","title":"COVID-19 tạo một đứt gãy hiếm thấy","text":"Đại dịch từ 2020 làm gián đoạn du lịch, sản xuất và đời sống thường ngày; các biện pháp y tế thay đổi qua nhiều giai đoạn trước khi đất nước mở cửa trở lại. Sau đó, phục hồi kinh tế diễn ra trong bối cảnh lạm phát toàn cầu, đứt gãy logistics và dịch chuyển chuỗi cung ứng."},{"kicker":"Hệ quả","title":"Hội nhập tiếp tục nhưng địa chính trị phức tạp hơn","text":"Việt Nam tiếp tục theo đuổi quan hệ rộng với nhiều đối tác và tham gia sâu vào các khuôn khổ thương mại khu vực. Đồng thời, Biển Đông, an ninh chuỗi cung ứng và cạnh tranh giữa các nước lớn khiến ngoại giao cân bằng trở thành một phần quan trọng của bối cảnh hiện đại."}],"transition":"Đây là thời kỳ còn đang diễn ra, vì vậy atlas không kể nó như một câu chuyện đã có kết luận. Các mốc gần hiện tại cần được cập nhật khi có tài liệu chính thức và khi lịch sử đủ khoảng cách để đánh giá tác động lâu dài.","note":""}];
function storyMarkup(i){const s=STORY_DATA[i];const note=s.note?`<div class="story-note"><strong>Lưu ý nguồn:</strong> ${s.note}</div>`:'';return `<div class="story-hero"><small>Câu chuyện thời kỳ</small><h4>${s.title}</h4><p>${s.lead}</p></div><div class="story-flow">${s.scenes.map((x,n)=>`<article class="story-scene"><div class="story-step">${String(n+1).padStart(2,'0')}</div><div><small>${x.kicker}</small><h5>${x.title}</h5><p>${x.text}</p></div></article>`).join('')}</div><div class="story-transition"><small>Chuyển sang thời kỳ kế tiếp</small><p>${s.transition}</p></div>${note}<div class="story-sources"><small>Đọc kèm nguồn</small>${readerSourcesMarkup(i)}</div>`}
function periodDetailTexts(p){return [`Cấu trúc quyền lực thay đổi theo từng giai đoạn. ${p[3]} là lực lượng/lãnh đạo tiêu biểu của thời kỳ đang xem.`,`Không gian chính trị tập trung quanh ${p[5]}; phần lãnh thổ trên bản đồ phải được đọc theo mức độ chắc chắn và nguồn dựng bản đồ của thời kỳ.`,`Kinh tế chủ yếu dựa trên nông nghiệp, thủ công và thương mại; mức độ đô thị hóa tăng rõ ở các thời kỳ muộn.`,`Văn hóa Việt Nam phát triển qua giao thoa bản địa, Đông Á và Đông Nam Á, với thay đổi lớn về tôn giáo, giáo dục và chữ viết.`,`${p[9]}. Quan hệ với các nước láng giềng thường là yếu tố quyết định biến động lãnh thổ.`,`Giai đoạn ${p[2]} để lại nền tảng cho thời kỳ kế tiếp; kéo thanh năm để theo dõi sự chuyển đổi.`]}
function territoryExplanation(i,y){const p=P[i];return i===0&&y<-700?'Niên đại Hồng Bàng sớm thuộc truyền thống sử học; atlas không vẽ một đường biên lãnh thổ khi chưa có cơ sở khảo cổ đủ để làm vậy.':i===0?'Văn Lang được thể hiện như địa bàn chủ yếu Bắc Bộ–Bắc Trung Bộ dựa trên địa lý lịch sử và phân bố Đông Sơn, không phải đường biên quốc gia đã khảo sát.':i===1?'Âu Lạc được tái dựng khái quát quanh chính thể Cổ Loa; biên giới chính xác vẫn không thể xác định như bản đồ hiện đại.':i<20?'Đường bao là vùng địa lý tái dựng khái quát theo các nguồn ghi trong mục Nguồn; không nên đọc nó như biên giới khảo sát hiện đại.':i<27?'Bản đồ dựa nhiều hơn vào tư liệu hành chính, bản đồ đương thời hoặc hiệp định; vùng kiểm soát trong chiến tranh vẫn chỉ là khái quát.':'Đường bao đất liền hiện đại dùng dữ liệu địa lý tham chiếu. Hoàng Sa và Trường Sa nằm trong lớp quần đảo riêng; yêu sách chủ quyền và kiểm soát thực tế được phân biệt.'}
function readerSourcesMarkup(i){const group=PERIOD_SOURCES[i];if(!group||!group.ids?.length)return '<p>Chưa có nguồn bản đồ riêng cho thời kỳ này.</p>';return group.ids.map(id=>{const x=MAP_SOURCE_CATALOG[id];return x?`<a class="reader-source" href="${x.url}" target="_blank" rel="noopener">↗ ${x.title}</a>`:''}).join('')+`<div class="reader-source-note">${sourceNoteFor(i,year)}</div>`}
function eraPeopleMarkup(i){const ids=PERIOD_PEOPLE[i]||[],people=ids.map(personById).filter(Boolean),groups=[['direct','Trực tiếp với lịch sử Việt Nam'],['regional','Khu vực / ảnh hưởng'],['world','Thế giới cùng thời']];return `<h4>Nhân vật · ${P[i][2]}</h4><p>Chọn một người để mở hồ sơ. Danh sách phân biệt người tham gia trực tiếp với những nhân vật chỉ được dùng để mở rộng bối cảnh khu vực hoặc thế giới.</p>${groups.map(([key,label])=>{const xs=people.filter(p=>p.relevance===key);if(!xs.length)return '';return `<section class="era-people-group"><h5>${label}</h5><div class="era-people-grid">${xs.map(p=>`<button class="era-person" type="button" data-person-link="${p.id}"><strong>${p.name}</strong><small>${personLifeLabel(p)} · ${p.polity}</small></button>`).join('')}</div></section>`}).join('')}`}
function findPersonByQuery(q){const n=normText(q);if(!n)return null;return PEOPLE.find(p=>normText(p.name)===n||(p.alt||[]).some(a=>normText(a)===n))||PEOPLE.find(p=>normText(p.name).startsWith(n))||PEOPLE.find(p=>normText([p.name,...(p.alt||[]),p.polity,...p.roles].join(' ')).includes(n))||null}
function openHashPerson(){if(!location.hash.startsWith('#person='))return;const id=decodeURIComponent(location.hash.slice(8));if(personById(id))openPerson(id)}
function readerContent(i,tab){const p=P[i],d=periodDetailTexts(p);if(tab==='story')return storyMarkup(i);const kv=`<div class="reader-kv"><div><small>Chính thể</small><strong>${p[4]}</strong></div><div><small>Kinh đô / trung tâm</small><strong>${p[5]}</strong></div><div><small>Độ chắc chắn</small><strong>${p[6]}</strong></div></div>`;if(tab==='overview')return `<h4>${p[2]}</h4><p>${p[7]}</p>${kv}<div class="reader-section"><h5>Nhà nước & chính trị</h5><p>${d[0]}</p></div><div class="reader-section"><h5>Di sản & chuyển tiếp</h5><p>${d[5]}</p></div>`;if(tab==='territory')return `<h4>Lãnh thổ & địa lý</h4>${kv}<p>${territoryExplanation(i,year)}</p><div class="reader-source-note">Hãy đối chiếu lớp màu trên bản đồ với mục “Nguồn” thay vì xem đường bao là tuyệt đối.</div>`;if(tab==='people')return eraPeopleMarkup(i);if(tab==='events')return `<h4>Sự kiện nổi bật</h4><ul><li>${p[8]}</li><li>${p[9]}</li></ul><p>Kéo thanh năm trong phạm vi ${fmt(p[0])} – ${fmt(p[1])} để xem bản đồ tại những thời điểm khác nhau của cùng thời kỳ.</p>`;if(tab==='war')return `<h4>Đối ngoại & chiến tranh</h4><p>${d[4]}</p><ul><li>${p[9]}</li><li>${p[8]}</li></ul><div class="reader-source-note">Mũi tiến quân, vùng kiểm soát và biên giới chiến sự—khi xuất hiện—là lớp lịch sử riêng, không đồng nghĩa với chủ quyền lâu dài.</div>`;if(tab==='culture')return `<h4>Văn hóa & xã hội</h4><div class="reader-section"><h5>Văn hóa & tư tưởng</h5><p>${d[3]}</p></div><div class="reader-section"><h5>Xã hội & kinh tế</h5><p>${d[2]}</p></div>`;return `<h4>Nguồn cho ${p[2]}</h4><p>Các nguồn dưới đây được dùng để định hướng việc dựng bản đồ và diễn giải thời kỳ.</p>${readerSourcesMarkup(i)}`}
function renderEraReader(i=selected,tab=readerTab){readerTab=tab;const p=P[i];$('readerEyebrow').textContent=`Thời kỳ ${String(i+1).padStart(2,'0')} / ${P.length}`;$('readerTitle').textContent=p[2];$('readerMeta').textContent=`${fmt(p[0])} – ${fmt(p[1])} · đang xem ${fmt(year)}`;$('readerTabs').innerHTML=readerTabs.map(([id,label])=>`<button class="reader-tab" type="button" role="tab" data-tab="${id}" aria-selected="${id===readerTab}">${label}</button>`).join('');$('readerTabs').querySelectorAll('.reader-tab').forEach(b=>b.onclick=()=>renderEraReader(i,b.dataset.tab));$('readerBody').innerHTML=readerContent(i,readerTab);$('readerBody').querySelectorAll('[data-person-link]').forEach(b=>b.onclick=()=>{$('eraReader').close();openPerson(b.dataset.personLink)})}
function openEraReader(i=selected){if(Number.isInteger(i)&&i!==selected)render(P[i][0]);readerTab='story';renderEraReader(selected,readerTab);const dlg=$('eraReader');if(typeof dlg.showModal==='function')dlg.showModal();else dlg.setAttribute('open','')}
let year=-2879,zoom=5,center={lat:16.2,lon:106.4},drag=null,selected=0,lastPeriod=-1;const $=id=>document.getElementById(id);const fmt=y=>y<0?`${Math.abs(y)} TCN`:`${y}`;
function idxFor(y){let i=P.findIndex(p=>y>=p[0]&&y<=p[1]);return i<0?(y<0?0:P.length-1):i}
function project(lat,lon,w,h){const n=2**zoom,x=(lon+180)/360*n,y=(1-Math.asinh(Math.tan(lat*Math.PI/180))/Math.PI)/2*n;const cx=(center.lon+180)/360*n,cy=(1-Math.asinh(Math.tan(center.lat*Math.PI/180))/Math.PI)/2*n;return{x:(x-cx)*256+w/2,y:(y-cy)*256+h/2}}
function tileXY(){const n=2**zoom;return{x:(center.lon+180)/360*n,y:(1-Math.asinh(Math.tan(center.lat*Math.PI/180))/Math.PI)/2*n,n}}
function drawMap(){drawOverlay()}
function drawOverlay(){const svg=$('overlay'),w=svg.clientWidth,h=svg.clientHeight;svg.setAttribute('viewBox',`0 0 ${w} ${h}`);const {territories,top}=SuVietBasemap.draw(svg,w,h,center,zoom);const layers=overlayFor(selected,year);for(const l of layers){const shape=overlaySets[l.k];if(!shape)continue;if(l.t==='line'){const pts=shape.map(([a,o])=>{const p=project(a,o,w,h);return`${p.x},${p.y}`}).join(' ');territories.insertAdjacentHTML('beforeend',`<polyline class="territory line" points="${pts}"/>`)}else{const parts=Array.isArray(shape[0]?.[0])?shape:[shape];for(const part of parts){const ps=part.map(([a,o])=>{const p=project(a,o,w,h);return`${p.x.toFixed(1)} ${p.y.toFixed(1)}`});const d=`M ${ps.join(' L ')} Z`;territories.insertAdjacentHTML('beforeend',`<path class="territory ${l.t}" d="${d}"/>`)}}}$('legend').classList.toggle('compact',layers.length<=1);$('legend').innerHTML=layers.length?layers.map(l=>`<div class="legend-row"><span class="legend-swatch ${l.t}"></span><span>${l.n}</span></div>`).join(''):`<div class="legend-row"><span>Không dựng đường biên cho niên đại truyền thống</span></div>`;if(selected>=20)$('legend').insertAdjacentHTML('beforeend',`<div class="legend-row legend-maritime"><span>◆</span><span>Hoàng Sa · Trường Sa — lớp quần đảo riêng</span></div>`);$('legend').insertAdjacentHTML('beforeend','<div class="legend-row"><span class="legend-swatch modern-border"></span><span>Biên giới ngày nay (để so sánh)</span></div>');drawMaritimeLayer(top,w,h);renderMapSources();const p=P[selected],caps=(p[5]||'').split('/').map(s=>s.trim()).slice(0,3);const coords={'Phong Châu':[21.42,105.2],'Cổ Loa':[21.12,105.88],'Mê Linh':[21.18,105.7],'Luy Lâu':[21.08,106.03],'Long Biên':[21.04,105.9],'Tống Bình':[21.03,105.85],'Đại La':[21.03,105.85],'Hoa Lư':[20.25,105.97],'Thăng Long':[21.03,105.85],'Tây Đô':[19.82,105.6],'Đông Quan':[21.03,105.85],'Đông Kinh':[21.03,105.85],'Phiên Ngung':[23.13,113.27],'Phú Xuân':[16.46,107.59],'Huế':[16.46,107.59],'Hà Nội':[21.03,105.85],'Sài Gòn':[10.78,106.7]};for(const c of caps){const k=Object.keys(coords).find(k=>c.includes(k));if(!k)continue;const q=project(...coords[k],w,h);top.insertAdjacentHTML('beforeend',`<g class="mark"><circle cx="${q.x}" cy="${q.y}" r="6"/><text x="${q.x+10}" y="${q.y+4}">${k}</text></g>`)} }
function render(y){year=+y;selected=idxFor(year);const view=periodView(selected,year),viewKey=[selected,view.lat,view.lon,view.zoom].join();if(viewKey!==lastPeriod){center={lat:view.lat,lon:view.lon};zoom=view.zoom;lastPeriod=viewKey}const p=P[selected];$('yearLabel').textContent=fmt(year);$('factYear').textContent=fmt(year);$('slider').value=year;$('position').textContent=String(selected+1).padStart(2,'0')+' / '+P.length;$('dynasty').textContent=p[2];$('confidence').textContent=p[6];$('leader').textContent=p[3];$('range').textContent=`${fmt(p[0])} – ${fmt(p[1])}`;$('state').textContent=p[4];$('capital').textContent=p[5];$('summary').textContent=p[7];$('events').innerHTML=`<li>${p[8]}</li><li>${p[9]}</li>`;$('mapNote').innerHTML=`<strong>${p[2]} · ${fmt(year)}</strong><br>${selected===0&&year<-2000?'Niên đại truyền thuyết, chưa có di chỉ khảo cổ cùng thời. Đường chấm là vùng 15 bộ Văn Lang theo truyền thống, nay thuộc Bắc Bộ và Bắc Trung Bộ (từ Cao Bằng, Lạng Sơn đến Quảng Bình, Quảng Trị). Đây không phải biên giới đo đạc.':selected===0&&year<-700?'Vùng tô: nơi có di chỉ cùng thời (sông Hồng: Phùng Nguyên → Đồng Đậu → Gò Mun; sông Mã: Cồn Chân Tiên → Bái Man → Quỳ Chử). Đó là nơi cư dân sống, chưa phải biên giới. Đường chấm: vùng 15 bộ Văn Lang theo truyền thống.':selected===0?'Văn Lang: vùng tô biểu diễn địa bàn chủ yếu Bắc Bộ–Bắc Trung Bộ theo địa lý lịch sử và phân bố Đông Sơn; không giả định đây là một đường biên chính xác.':selected===1?'Âu Lạc: vùng tô là tái dựng khái quát quanh chính thể Cổ Loa, không phải biên giới khảo sát.':selected<20?'Đường bao là vùng địa lý tái dựng khái quát theo nguồn ghi trong “Nguồn dựng bản đồ”; không nội suy thành đường cong hay coi là biên giới khảo sát.':selected<27?'Bản đồ dùng tư liệu hành chính, bản đồ đương thời hoặc hiệp định; vùng chiến sự vẫn là khái quát.':'Đường bao đất liền hiện đại dùng dữ liệu địa lý tham chiếu. Hoàng Sa và Trường Sa hiển thị bằng lớp quần đảo riêng; yêu sách chủ quyền và kiểm soát thực tế không được gộp làm một.'}`;const texts=periodDetailTexts(p);$('details').innerHTML=detailTitles.map((t,i)=>`<article class="detail"><h4>${t}</h4><p>${texts[i]}</p></article>`).join('');document.querySelectorAll('.pcard').forEach((c,i)=>c.classList.toggle('active',i===selected));drawMap();renderPeopleHub();if($('eraReader').open)renderEraReader(selected,readerTab)}
function makeCards(){ $('cards').innerHTML=P.map((p,i)=>`<article class="pcard" data-i="${i}"><button class="period-select" type="button" data-i="${i}"><span>${String(i+1).padStart(2,'0')} / ${P.length}</span><strong>${p[2]}</strong><small>${fmt(p[0])} – ${fmt(p[1])}</small></button><button class="period-read" type="button" data-i="${i}">Đọc câu chuyện</button></article>`).join('');document.querySelectorAll('.period-select').forEach(b=>b.onclick=()=>{const p=P[+b.dataset.i];render(p[0]);$('explore').scrollIntoView({behavior:'smooth'})});document.querySelectorAll('.period-read').forEach(b=>b.onclick=()=>openEraReader(+b.dataset.i))}
$('closePerson').onclick=()=>{$('personDialog').close();if(location.hash.startsWith('#person='))history.replaceState(null,'',location.pathname+location.search)};$('personDialog').addEventListener('click',e=>{if(e.target===$('personDialog'))$('closePerson').click()});$('openReader').onclick=()=>openEraReader(selected);$('closeReader').onclick=()=>$('eraReader').close();$('eraReader').addEventListener('click',e=>{if(e.target===$('eraReader'))$('eraReader').close()});$('slider').oninput=e=>render(e.target.value);$('zin').onclick=()=>{zoom=Math.min(9,zoom+1);drawMap()};$('zout').onclick=()=>{zoom=Math.max(3,zoom-1);drawMap()};$('map').onpointerdown=e=>{if(e.target.closest('.zoom,.map-mode,.attrib,.mapnote,.legend,.map-sources'))return;drag={x:e.clientX,y:e.clientY,lat:center.lat,lon:center.lon};$('map').classList.add('drag');$('map').setPointerCapture(e.pointerId)};$('map').onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y,n=2**zoom,cx=(drag.lon+180)/360*n-dx/256,cy=(1-Math.asinh(Math.tan(drag.lat*Math.PI/180))/Math.PI)/2*n-dy/256;center.lon=cx/n*360-180;center.lat=Math.atan(Math.sinh(Math.PI*(1-2*cy/n)))*180/Math.PI;drawMap()};$('map').onpointerup=e=>{drag=null;$('map').classList.remove('drag')};$('search').onkeydown=e=>{if(e.key!=='Enter')return;const raw=e.target.value.trim(),q=normText(raw);let y=parseInt(q);if(/tcn/.test(q))y=-Math.abs(y);if(Number.isFinite(y)&&y>=-2879&&y<=2026)return render(y);const person=findPersonByQuery(raw);if(person)return openPerson(person.id);const i=P.findIndex(p=>normText(p.slice(2,8).join(' ')).includes(q));if(i>=0)render(P[i][0])};window.addEventListener('resize',drawMap);window.addEventListener('hashchange',openHashPerson);makeCards();bindPeopleHub();render(year);openHashPerson();
